 26: function CheckoutSuccessContent() {
 27:   const router = useRouter();
 28:   const params = useSearchParams();
 29:   const orderNumber = params.get('order') ?? '';
 30:   // sessionStorage survives refresh in the same tab. A new tab without it
 31:   // falls back to the phone-verified track page (track requires the order phone).
 32:   const [order, setOrder] = useState<StoreOrder | null>(null);
 33:   const [loading, setLoading] = useState(true);
 34:   const token = useAuthStore((s) => s.token);
 35:   const hydrated = useAuthHydrated();
 36:   useEffect(() => {
 37:     if (!hydrated) return;
 38:     let active = true;
 39:     setLoading(true);
 40:     let receipt: StoreOrder | null = null;
 41:     try {
 42:       const raw = sessionStorage.getItem('last_order');
 43:       const parsed = raw ? (JSON.parse(raw) as StoreOrder) : null;
 44:       if (parsed && parsed.order_number === orderNumber && Array.isArray(parsed.items)
 45:         && Number.isFinite(Number(parsed.grand_total))) receipt = parsed;
 46:     } catch { /* Without storage, signed-in shoppers can recover their own receipt. */ }
 47:     setOrder(receipt);
 48:     if (receipt || !token || !orderNumber) { setLoading(false); return; }
 49:     accountEndpoints.orders().then((orders) => {
 50:       if (active) setOrder(orders.find((o) => o.order_number === orderNumber) ?? null);
 51:     }).catch(() => {}).finally(() => { if (active) setLoading(false); });
 52:     return () => { active = false; };
 53:   }, [orderNumber, token, hydrated]);
 54: 
 55:   return (
 56:     <main className="min-h-screen bg-[#f3f5f7]">
 57:       <section className="checkout-wrapper" aria-label="Order success">
 58:         <div className="container" style={{ maxWidth: '720px', margin: '0 auto', padding: '40px 20px' }}>
 59:           {loading ? (
 60:             <div aria-hidden="true">
 61:               <div className="mega-skel-title" style={{ width: '40%' }} />
 62:               <div className="mega-skel-link" />
 63:               <div className="mega-skel-link" />
 64:             </div>
 65:           ) : order ? (
 66:             <div className="order-modal-card" style={{ margin: '0 auto' }}>
 67:               <div className="order-modal-icon">
 68:                 <i className="fa-solid fa-check" aria-hidden="true" />
 69:               </div>
 70:               <h1 className="order-modal-title">تم استلام طلبك!</h1>
 71:               <p className="order-modal-desc">
 72:                 رقم الطلب <strong>{order.order_number}</strong>
 73:               </p>
 74:               <div className="bag-items-list">
 75:                 {order.items.map((item) => (
 76:                   <div key={item.id} className="bag-item-row">
 77:                     <div className="bag-item-info">
 78:                       <h4 className="bag-item-title">{item.product_name}</h4>
 79:                       <div className="bag-item-meta">
 80:                         <span className="meta-label">Quantity:</span>
 81:                         <span className="meta-val">{item.qty}</span>
 82:                       </div>
 83:                     </div>
 84:                     <div className="bag-item-right">
 85:                       <span className="bag-item-price">{formatStorePrice(Number(item.line_total))}</span>
 86:                     </div>
 87:                   </div>
 88:                 ))}
 89:               </div>
 90:               <div className="bag-totals-row">
 91:                 <span>الإجمالي</span>
 92:                 <strong>{formatStorePrice(Number(order.grand_total))}</strong>
 93:               </div>
 94:               <div className="bag-totals-row">
 95:                 <span>طريقة الدفع</span>
 96:                 <strong>{paymentLabels[order.payment_method] ?? order.payment_method}</strong>
 97:               </div>
 98:               <div className="checkout-success-actions">
 99:                 <Link
100:                   href={`/orders/${encodeURIComponent(order.order_number)}/track`}
101:                   className="btn-place-order"
102:                 >
103:                   تتبع طلبك
104:                 </Link>
105:                 <button
106:                   type="button"
107:                   className="back-to-shop-btn"
108:                   onClick={() => router.push('/shop')}
109:                 >
110:                   كمّل تسوق
111:                 </button>
112:               </div>
113:             </div>
114:           ) : (
115:             <div className="order-modal-card" style={{ margin: '0 auto', textAlign: 'center' }}>
116:               <h1 className="order-modal-title">{orderNumber ? `الطلب ${orderNumber}` : 'لا يوجد طلب لعرضه'}</h1>
117:               <p className="order-modal-desc">{orderNumber ? 'تقدر تتحقق من تفاصيل طلبك برقمه ورقم الموبايل.' : 'اطلب أولاً أو تابع طلبك برقمه ورقم الموبايل.'}</p>
118:               <div className="checkout-success-actions">
119:                 {orderNumber ? (
120:                   <Link href={`/orders/${encodeURIComponent(orderNumber)}/track`} className="btn-place-order">تتبع طلبك</Link>
121:                 ) : (
122:                   <Link href="/shop" className="btn-place-order">تسوّق الآن</Link>
123:                 )}
124:               </div>
125:             </div>
126:           )}
127:         </div>
128:       </section>
129:       <SophieFooter />
130:     </main>
131:   );
132: } 1: 'use client';
