 6: interface StageImage { url: string | null; alt: string }
 7: interface ShowcaseStageProps {
 8:   previous: StageImage;
 9:   current: StageImage;
10:   next: StageImage;
11:   canNavigate: boolean;
12:   onNavigate: (direction: number) => void;
13:   onExplore?: () => void;
14: }
15: 
16: /** The same three-slot stage is used when browsing and configuring a product. */
17: export function ShowcaseStage({ previous, current, next, canNavigate, onNavigate, onExplore }: ShowcaseStageProps) {
18:   return <div className="showcase-stage-scene" role="region" aria-label="Interactive product stage" tabIndex={0}
19:     onKeyDown={(event) => { if (canNavigate && ['ArrowLeft', 'ArrowRight'].includes(event.key)) { event.preventDefault(); event.stopPropagation(); onNavigate(event.key === 'ArrowRight' ? 1 : -1); } }}>
20:     {canNavigate && <><button type="button" className="design-carousel-arrow prev" aria-label="Previous product image" onClick={() => onNavigate(-1)}><ChevronLeft size={19} /></button><button type="button" className="design-carousel-arrow next" aria-label="Next product image" onClick={() => onNavigate(1)}><ChevronRight size={19} /></button></>}
21:     <div className="design-stage">
22:       <button type="button" className="design-bag-slot left" aria-label="Previous stage view" disabled={!canNavigate} onClick={() => onNavigate(-1)}>
23:         {previous.url && <StoreImage src={previous.url} alt={previous.alt} draggable={false} />}<div className="design-bag-shadow" />
24:       </button>
25:       <div className="design-bag-slot center" onClick={onExplore} role={onExplore ? 'button' : undefined} tabIndex={onExplore ? 0 : undefined} onKeyDown={(event) => { if (onExplore && ['Enter', ' '].includes(event.key)) { event.preventDefault(); onExplore(); } }}>
26:         {current.url ? <StoreImage className="product-stage-image" src={current.url} alt={current.alt} draggable={false} /> : <p className="product-image-empty">Product photography coming soon</p>}<div className="design-bag-shadow" />
27:       </div>
28:       <button type="button" className="design-bag-slot right" aria-label="Next stage view" disabled={!canNavigate} onClick={() => onNavigate(1)}>
29:         {next.url && <StoreImage src={next.url} alt={next.alt} draggable={false} />}<div className="design-bag-shadow" />
30:       </button>
31:     </div>
32:   </div>;
33: } 1: 'use client';
