 3: import { useState } from 'react';
 4: import { ArrowLeft, Check, ChevronDown, ShoppingBag } from 'lucide-react';
 5: import { formatStorePrice } from '@alfarid/utils';
 6: import type { StoreProduct } from '@alfarid/api-client';
 7: import { toDetailVM } from '@/lib/catalog-mappers';
 8: import { initialProductSelection } from '@/lib/product-selection';
 9: import { useCartStore } from '@/stores/cart-store';
10: import { ShowcaseStage } from '@/components/design/ShowcaseStage';
11: 
12: export function ProductExperience({ product, onBack, initialColor, initialSize }: {
13:   product: StoreProduct; onBack: () => void; initialColor?: string | null; initialSize?: string | null;
14: }) {
15:   const detail = toDetailVM(product);
16:   const [selection, setSelection] = useState(() => initialProductSelection(detail, initialColor, initialSize));
17:   const { size, color } = selection;
18:   const [quantity, setQuantity] = useState(1);
19:   const [activeImage, setActiveImage] = useState<string | null>(null);
20:   const [adding, setAdding] = useState(false);
21:   const [added, setAdded] = useState(false);
22:   const [notice, setNotice] = useState('');
23:   const addItem = useCartStore((state) => state.addItem);
24:   const sizeReady = detail.sizes.length === 0 || size !== null;
25:   const complete = sizeReady && color !== null;
26:   const soldOut = !detail.variants.some((item) => item.inStock && item.price !== null);
27:   const variant = complete ? detail.variants.find((item) => item.colorKey === color && item.sizeLabel === size) ?? null : null;
28:   const preview = variant ?? detail.variants.find((item) => (!color || item.colorKey === color) && (!size || item.sizeLabel === size) && item.inStock) ?? detail.variants[0];
29:   const maxQty = variant?.maxQty ?? 0;
30:   const selectedQty = Math.min(quantity, maxQty);
31:   const canBuy = !!variant?.inStock && variant.price !== null && maxQty >= 1;
32:   const price = variant ? variant.price : detail.fallbackPrice;
33:   const candidates = detail.variants.filter((item) => !sizeReady || item.sizeLabel === size);
34:   const slides = [...new Map(candidates.flatMap((item) => (item.images.length ? item.images : detail.images).map((photo) => ({ ...photo, key: item.colorKey + '|' + photo.url, colorKey: item.colorKey, colorLabel: item.colorLabel }))).map((photo) => [photo.key, photo])).values()];
35:   const selectedIndex = slides.findIndex((photo) => photo.key === activeImage && (!color || photo.colorKey === color));
36:   const colorIndex = slides.findIndex((photo) => photo.colorKey === (color ?? preview?.colorKey));
37:   const index = selectedIndex >= 0 ? selectedIndex : Math.max(0, colorIndex);
38:   const photoAt = (offset: number) => slides.length ? slides[(index + offset + slides.length) % slides.length] : null;
39:   const stageImage = (offset: number) => { const photo = photoAt(offset); return { url: photo?.url ?? product.image, alt: detail.name + (photo ? ' — ' + photo.colorLabel : '') }; };
40:   const resetFeedback = () => { setActiveImage(null); setAdded(false); setNotice(''); };
41:   const chooseSize = (nextSize: string) => {
42:     const available = detail.variants.filter((item) => item.sizeLabel === nextSize && item.inStock && item.price !== null);
43:     const colors = [...new Set(available.map((item) => item.colorKey))];
44:     setSelection({ size: nextSize, color: color && colors.includes(color) ? color : colors.length === 1 ? colors[0] : null });
45:     resetFeedback();
46:   };
47:   const chooseColor = (nextColor: string) => { setSelection((state) => ({ ...state, color: nextColor })); resetFeedback(); };
48:   const navigate = (direction: number) => { const photo = photoAt(direction); if (photo) { setSelection((state) => ({ ...state, color: photo.colorKey })); setActiveImage(photo.key); setAdded(false); setNotice(''); } };
49:   const add = async () => {
50:     if (!variant || !canBuy || adding) return;
51:     setAdding(true); setNotice('');
52:     try { const ok = await addItem(variant.id, selectedQty); setAdded(ok); setNotice(ok ? 'Added ' + selectedQty + ' × ' + detail.name + ' to your shopping bag.' : useCartStore.getState().error ?? 'Could not add to bag. Please try again.'); }
53:     finally { setAdding(false); }
54:   };
55:   const prompt = !sizeReady ? 'Choose your size' : !color ? 'Choose your color' : 'Your selection';
56: 
57:   return <article className="design-page product-experience product-mode">
58:     <section className="product-purchase-stage" aria-label="Product selection and 3D stage">
59:       <aside id="product-options" className="design-sidebar product-configurator" aria-label="Product options">
60:         <button className="product-back" onClick={onBack}><ArrowLeft size={14} /> Back to collection</button>
61:         <div className="design-sidebar-tag">{'// YOUR PIECE'}</div>
62:         <h2 className="product-selection-prompt" aria-live="polite">{prompt}</h2>
63:         {initialColor && color === initialColor.toLowerCase() && <p className="product-filter-selection">Color selected from your filters</p>}
64:         {detail.sizes.length > 0 && <fieldset className="product-option"><legend>Size / volume</legend><div className="product-size-options">{detail.sizes.map((option) => <button key={option} type="button" aria-pressed={size === option} disabled={!detail.variants.some((item) => item.sizeLabel === option && item.inStock && item.price !== null)} onClick={() => chooseSize(option)}>{option}</button>)}</div></fieldset>}
65:         {sizeReady && <fieldset className="product-option"><legend>Color{color && <strong>{detail.colors.find((item) => item.key === color)?.label}</strong>}</legend><div className="product-color-options">{detail.colors.map((option) => {
66:           const available = detail.variants.some((item) => item.colorKey === option.key && item.sizeLabel === size && item.inStock && item.price !== null);
67:           return <button key={option.key} type="button" aria-label={option.label} aria-pressed={color === option.key} title={option.label} disabled={!available} onClick={() => chooseColor(option.key)}><span className="product-color-dot" style={{ background: option.hex ?? '#ccc' }}>{color === option.key && <Check size={15} />}</span><span>{option.label}</span></button>;
68:         })}</div></fieldset>}
69:         {complete && <div className="product-option product-quantity"><label htmlFor={'product-quantity-' + product.id}>Quantity</label><div className="product-quantity-control"><button type="button" aria-label="Decrease quantity" disabled={selectedQty <= 1} onClick={() => { setQuantity(selectedQty - 1); setAdded(false); }}>−</button><input id={'product-quantity-' + product.id} aria-label="Quantity" type="number" min={1} max={maxQty} disabled={!canBuy} value={selectedQty} onChange={(event) => { setQuantity(Math.max(1, Math.min(maxQty, Math.floor(Number(event.target.value) || 1)))); setAdded(false); }} /><button type="button" aria-label="Increase quantity" disabled={!canBuy || selectedQty >= maxQty} onClick={() => { setQuantity(selectedQty + 1); setAdded(false); }}>+</button></div></div>}
70:         <button className="design-btn-pill product-add-button" disabled={!canBuy || adding} onClick={add}>{added ? <Check size={16} /> : <ShoppingBag size={16} />}{soldOut ? 'Sold out' : !complete ? !sizeReady ? 'Choose size' : 'Choose color' : adding ? 'Adding…' : added ? 'Added to cart' : !canBuy ? 'Sold out' : 'Add to cart'}</button>
71:         <p className="product-cart-notice" role="status">{notice}</p>
72:         {variant && <p className="product-variant-sku">SKU: {variant.sku}</p>}
73:       </aside>
74:       <div className="design-carousel-view product-visual">
75:         <ShowcaseStage previous={stageImage(-1)} current={stageImage(0)} next={stageImage(1)} canNavigate={slides.length > 1} onNavigate={navigate} />
76:         <div className="design-carousel-info product-heading"><h1 className="design-brand-title">{detail.categoryLabel || 'The collection'}</h1><p className="design-bag-subtitle">{detail.name} &nbsp;|&nbsp; {price !== null ? formatStorePrice(price) : 'Unavailable'}</p><p className="product-stage-selection">{[size, detail.colors.find((item) => item.key === color)?.label].filter(Boolean).join(' / ') || prompt}</p><a className="design-btn-pill product-details-link" href={complete ? '#product-details' : '#product-options'}>{complete ? 'Explore details' : prompt} <ChevronDown size={15} /></a></div>
77:         <a className="design-scroll-hint" href="#product-details"><ChevronDown size={14} /> Scroll to discover the details</a>
78:       </div>
79:     </section>
80:     <section id="product-details" className="product-fine-details" aria-labelledby="product-details-title">
81:       <div><h2 id="product-details-title">A closer look</h2><p>{detail.desc || 'More product details will be available soon.'}</p></div>
82:       <dl>
83:         {detail.material && <div><dt>Material & craftsmanship</dt><dd>{detail.material}</dd></div>}
84:         {product.dimensions && [product.dimensions.length_cm, product.dimensions.width_cm, product.dimensions.height_cm].some((value) => value != null) && <div><dt>Dimensions</dt><dd>{[['Length', product.dimensions.length_cm], ['Width', product.dimensions.width_cm], ['Height', product.dimensions.height_cm]].filter(([, value]) => value != null).map(([label, value]) => `${label}: ${value} cm`).join(' · ')}</dd></div>}
85:         {product.dimensions?.weight_kg != null && <div><dt>Weight</dt><dd>{product.dimensions.weight_kg} kg</dd></div>}
86:         {(product.warranty_details || detail.warrantyMonths) && <div><dt>Warranty</dt><dd>{product.warranty_details || `${detail.warrantyMonths}-month warranty.`}</dd></div>}
87:         {product.country_of_origin && <div><dt>Country of origin</dt><dd>{product.country_of_origin}</dd></div>}
88:         <div><dt>Selected piece</dt><dd>{[variant?.sizeLabel, variant?.colorLabel, variant?.sku].filter(Boolean).join(' · ') || detail.name}</dd></div>
89:       </dl>
90:     </section>
91:   </article>;
92: } 1: 'use client';
