 6: export function ContactSection({ vm }: { vm: CheckoutVM }) {
 7:   const { form, set, blur, visibleErrors } = vm;
 8:   return (
 9:     <div className="checkout-block">
10:       <div className="checkout-block-header">
11:         <h2 className="checkout-section-heading">Information</h2>
12:         {!vm.token && (
13:           <p className="checkout-login-prompt">
14:             عندك حساب؟{' '}
15:             <a href={`/auth/login?redirect=${encodeURIComponent('/checkout')}`}>
16:               سجّل دخول عشان نملالك البيانات
17:             </a>
18:           </p>
19:         )}
20:       </div>
21: 
22:       <h3 className="checkout-subheading">Personal Information</h3>
23:       <div className="checkout-fields-grid">
24:         <div className="line-input-wrap">
25:           <input
26:             type="text"
27:             id="chk-fullname"
28:             aria-label="الاسم بالكامل"
29:             maxLength={255}
30:             className="line-input"
31:             placeholder="الاسم بالكامل"
32:             autoComplete="name"
33:             value={form.fullName}
34:             onChange={(e) => set('fullName', e.target.value)}
35:             onBlur={() => blur('fullName')}
36:             aria-invalid={!!visibleErrors.fullName}
37:             data-checkout-error={visibleErrors.fullName ? 'true' : undefined}
38:           />
39:           {visibleErrors.fullName && <p className="luxury-field-error" role="alert">{visibleErrors.fullName}</p>}
40:         </div>
41:         <div className="line-input-wrap">
42:           <input
43:             type="tel"
44:             id="chk-phone"
45:             aria-label="رقم الموبايل"
46:             maxLength={50}
47:             className="line-input"
48:             placeholder="رقم الموبايل"
