 11: export interface SuggestionCard { slug: string; name: string; img: string | null; priceLabel: string }
 12: 
 13: export function OrderSummary({ vm, suggestions }: { vm: CheckoutVM; suggestions: SuggestionCard[] }) {
 14:   const {
 15:     items, cartLoading, totals, couponCode, quote,
 16:     updateQuantity, removeItem, applyCoupon, removeCoupon,
 17:     promoInput, setPromoInput, setBanner,
 18:   } = vm;
 19:   const [overrides, setOverrides] = useState<Record<number, number>>({});
 20:   const [promoBusy, setPromoBusy] = useState(false);
 21:   const changing = useRef(false);
 22: 
 23:   const preview = quote?.preview ?? null;
 24:   const shownItemsTotal = preview?.items_total ?? totals?.items_total ?? 0;
 25:   const shownCoupon = preview?.coupon_discount ?? totals?.coupon_discount ?? 0;
 26:   const shownShipping = preview?.shipping ?? 0;
 27:   const shownCod = preview?.cod_fee ?? 0;
 28:   const shownTax = preview?.tax ?? 0;
 29:   const shownGrand = preview?.grand_total;
 30: 
 31:   const changeQty = async (id: number, current: number, delta: number) => {
 32:     const item = items.find((i) => i.id === id);
 33:     if (!item || changing.current || vm.cartBusy || !item.priced) return;
 34:     const next = current + delta;
 35:     if (next < 1 || next > item.available) return;
 36:     changing.current = true;
 37:     // Optimistic update — revert to the server value on failure.
 38:     setOverrides((o) => ({ ...o, [id]: next }));
 39:     const ok = await updateQuantity(id, next);
 40:     changing.current = false;
 41:     setOverrides((o) => {
 42:       const copy = { ...o };
 43:       delete copy[id];
 44:       return copy;
 45:     });
 46:     if (!ok) setBanner({ kind: 'error', text: 'مقدرناش نحدّث الكمية، حاول تاني.' });
 47:   };
 48: 
 49:   const submitPromo = async () => {
 50:     const code = promoInput.trim();
 51:     if (!code || promoBusy) return;
 52:     setPromoBusy(true);
 53:     const ok = await applyCoupon(code);
 54:     setPromoBusy(false);
 55:     if (!ok) setBanner({ kind: 'error', text: useCartStore.getState().error || 'كود الخصم غير صالح أو منتهي.' });
 56:     else setPromoInput('');
 57:   };
 58: 
 59:   if (!cartLoading && items.length === 0) {
 60:     return (
 61:       <div className="bag-summary-panel">
 62:         <h2 className="checkout-section-heading">Shopping Bag (0)</h2>
 63:         <div className="checkout-empty-bag">
 64:           <i className="fa-solid fa-bag-shopping" aria-hidden="true" />
 65:           <p>سلتك فاضية. اكتشف المجموعة واختار اللي يعجبك.</p>
 66:           <Link href="/shop" className="btn-place-order">تسوّق الآن</Link>
 67:         </div>
 68:         {suggestions.length > 0 && (
 69:           <div className="checkout-suggestions">
 70:             <h3 className="checkout-subheading">مقترحات ليك</h3>
 71:             <div className="checkout-suggestions-grid">
 72:               {suggestions.slice(0, 4).map((s) => (
 73:                 <Link key={s.slug} href={`/shop?product=${encodeURIComponent(s.slug)}`} className="checkout-suggestion-card">
 74:                   {s.img ? <StoreImage src={s.img} alt={s.name} loading="lazy" /> : <span className="checkout-suggestion-ph" aria-hidden="true" />}
 75:                   <span className="checkout-suggestion-name">{s.name}</span>
 76:                   <span className="checkout-suggestion-price">{s.priceLabel}</span>
 77:                 </Link>
 78:               ))}
 79:             </div>
 80:           </div>
 81:         )}
 82:       </div>
 83:     );
 84:   }
 85: 
 86:   return (
 87:     <div className="bag-summary-panel">
 88:       <h2 className="checkout-section-heading" id="shopping-bag-heading">
 89:         Shopping Bag ({items.reduce((n, i) => n + i.quantity, 0)})
 90:       </h2>
 91: 
 92:       {cartLoading && items.length === 0 ? (
 93:         <div className="bag-items-list" aria-hidden="true">
 94:           {[1, 2, 3].map((i) => (
 95:             <div key={i} className="bag-item-row">
 96:               <div className="mega-spotlight-skel-img" style={{ width: 72, height: 90 }} />
 97:               <div style={{ flex: 1 }}>
 98:                 <div className="mega-skel-title" />
 99:                 <div className="mega-skel-link" />
100:               </div>
101:             </div>
102:           ))}
103:         </div>
104:       ) : (
105:         <div className="bag-items-list" id="bag-items-container">
106:           {items.map((item) => {
107:             const qty = overrides[item.id] ?? item.quantity;
108:             const atCap = qty >= item.available;
109:             return (
110:               <div
111:                 key={item.id}
112:                 className={`bag-item-row${item.priced ? '' : ' is-unavailable'}`}
113:                 data-bag-id={item.id}
114:               >
115:                 <div className="bag-item-thumb">
116:                   <StoreProductImage src={item.image} alt={item.name} />
117:                 </div>
118: 
119:                 <div className="bag-item-info">
120:                   <h4 className="bag-item-title">{item.slug ? <Link href={`/shop?product=${encodeURIComponent(item.slug)}`}>{item.name}</Link> : item.name}</h4>
121:                   <div className="bag-item-meta">
122:                     {item.color && (<><span className="meta-label">Color:</span><span className="meta-val">{item.color}</span></>)}
123:                     {item.size && (<><span className="meta-label">Size:</span><span className="meta-val">{item.size}</span></>)}
124:                     <span className="meta-label">Quantity:</span>
125:                     <span className="meta-val qty-stepper">
126:                       <button type="button" className="qty-btn" onClick={() => changeQty(item.id, qty, -1)} aria-label="Decrease quantity" disabled={qty <= 1 || vm.cartBusy || overrides[item.id] !== undefined || !item.priced}>-</button>
127:                       <span>{qty}</span>
128:                       <button
129:                         type="button" className="qty-btn" onClick={() => changeQty(item.id, qty, 1)} aria-label="Increase quantity"
130:                         disabled={atCap || vm.cartBusy || overrides[item.id] !== undefined || !item.priced} title={atCap ? 'أقصى كمية متاحة' : undefined}
131:                       >+</button>
132:                     </span>
133:                   </div>
134:                   {!item.priced && <p className="bag-item-unavailable">غير متاح <button type="button" className="bag-remove-btn" onClick={() => removeItem(item.id)}>حذف</button></p>}
135:                 </div>
136: 
137:                 <div className="bag-item-right">
138:                   <span className="bag-item-price">
139:                     {overrides[item.id] !== undefined ? 'جاري التحديث...' : item.priced ? formatStorePrice(item.lineTotal) : 'غير متاح'}
140:                   </span>
141:                   {item.priced && (
142:                     <button type="button" className="bag-remove-btn" onClick={() => removeItem(item.id)} title="Remove item">
143:                       <i className="fa-regular fa-trash-can" aria-hidden="true" /> Remove
144:                     </button>
145:                   )}
146:                 </div>
147:               </div>
148:             );
149:           })}
150:         </div>
151:       )}
152: 
153:       {couponCode ? (
154:         <div className="promo-chip-row">
155:           <span className="promo-chip">{couponCode}
156:             <button type="button" onClick={() => removeCoupon()} aria-label="إزالة الكوبون">✕</button>
157:           </span>
158:         </div>
159:       ) : (
160:         <div className="promo-row">
161:           <div className="line-input-wrap">
162:             <input
163:               type="text"
164:               className="line-input"
165:               id="promo-code-input"
166:               placeholder="كود الخصم"
167:               value={promoInput}
168:               onChange={(e) => setPromoInput(e.target.value)}
169:               onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); submitPromo(); } }}
170:             />
171:           </div>
172:           <button type="button" className="btn-apply-promo" id="apply-promo-btn" onClick={submitPromo} disabled={promoBusy}>
173:             {promoBusy ? '...' : 'APPLY'}
174:           </button>
175:         </div>
176:       )}
177: 
178:       <div className="bag-totals-row">
179:         <span>Subtotal</span>
180:         <strong>{formatStorePrice(shownItemsTotal)}</strong>
181:       </div>
182:       {shownCoupon > 0 && (
183:         <div className="bag-totals-row">
184:           <span>Discount{couponCode ? ` (${couponCode})` : ''}</span>
185:           <strong>-{formatStorePrice(shownCoupon)}</strong>
186:         </div>
187:       )}
188:       <div className="bag-totals-row">
189:         <span>Shipping</span>
190:         <strong id="summary-shipping">{!preview ? (vm.quoteLoading ? 'جاري الحساب...' : 'اختار المدينة') : shownShipping === 0 ? 'Free' : formatStorePrice(shownShipping)}</strong>
191:       </div>
192:       {shownCod > 0 && (
193:         <div className="bag-totals-row">
194:           <span>COD fee</span>
195:           <strong>{formatStorePrice(shownCod)}</strong>
196:         </div>
197:       )}
198:       {shownTax > 0 && (
199:         <div className="bag-totals-row">
200:           <span>Tax</span>
201:           <strong>{formatStorePrice(shownTax)}</strong>
202:         </div>
203:       )}
204: 
205:       <div className="bag-grand-total">
206:         <span>Total:</span>
207:         <span className="total-amount" id="summary-total" aria-live="polite">{shownGrand === undefined ? '—' : formatStorePrice(shownGrand)}</span>
208:       </div>
209:     </div>
210:   );
