 10: import { DeliverySection } from './DeliverySection';
 11: import { PaymentSection } from './PaymentSection';
 12: import { OrderSummary, type SuggestionCard } from './OrderSummary';
 13: 
 14: const steps = ['بيانات', 'الشحن', 'الدفع'];
 15: 
 16: /**
 17:  * Real-data checkout page: contact + shipping + delivery + payment sections
 18:  * on the left, live server-priced order summary on the right.
 19:  */
 20: export function SophieCheckoutPage({
 21:   onContinueShopping,
 22: }: {
 23:   onContinueShopping?: () => void;
 24:   onLoginClick?: () => void;
 25:   onOrderPlaced?: (orderData: unknown) => void;
 26: }) {
 27:   const vm = useCheckout();
 28:   const [suggestions, setSuggestions] = useState<SuggestionCard[]>([]);
 29: 
 30:   useEffect(() => {
 31:     let cancelled = false;
 32:     storeEndpoints.showcase().then((products) => {
 33:       if (cancelled) return;
 34:       setSuggestions(products.map(toCardVM).filter((c) => c.inStock).slice(0, 4)
 35:         .map((c) => ({ slug: c.slug, name: c.name, img: c.img, priceLabel: c.priceLabel })));
 36:     }).catch(() => {});
 37:     return () => { cancelled = true; };
 38:   }, []);
 39: 
 40:   const grand = vm.quote?.preview?.grand_total ?? null;
 41: 
 42:   return (
 43:     <section className="checkout-wrapper" id="checkout-view" aria-label="Checkout">
 44:       <div className="container" style={{ maxWidth: '1140px', margin: '0 auto', padding: '0 20px' }}>
 45:         <div className="checkout-top-bar">
 46:           <h1 className="checkout-giant-title">CHECKOUT</h1>
 47:           <button type="button" className="back-to-shop-btn" id="back-to-shop-btn" onClick={onContinueShopping}>
 48:             <i className="fa-solid fa-arrow-left" aria-hidden="true" /> Continue Shopping
 49:           </button>
 50:         </div>
 51: 
 52:         {/* Steps indicator */}
 53:         <ol className="checkout-steps" aria-label="Checkout steps">
 54:           {steps.map((label, i) => {
 55:             const n = i + 1;
 56:             const done = vm.step > n;
 57:             const current = vm.step === n;
 58:             return (
 59:               <li key={label} className={`checkout-step${done ? ' is-done' : ''}${current ? ' is-current' : ''}`} aria-current={current ? 'step' : undefined}>
 60:                 <span className="checkout-step-dot" aria-hidden="true">{done ? '✓' : n}</span>
 61:                 <span>{label}</span>
 62:               </li>
 63:             );
 64:           })}
 65:         </ol>
 66: 
