19: export function SophieHomeContent() {
20:   const { data, isPending, isError, refetch } = useStoreHome();
21:   const banners = data?.banners ?? EMPTY_BANNERS;
22:   const slides = useMemo(() => banners.filter((banner) => banner.position === 'main_slider').map(bannerToSlide), [banners]);
23:   const promos = useMemo(() => banners.filter((banner) => banner.position === 'middle_banner'), [banners]);
24:   const popup = banners.find((banner) => banner.position === 'popup');
25:   const best = useMemo(() => mapCards(data?.best_sellers, 'auto'), [data]);
26:   const latest = useMemo(() => mapCards(data?.latest_products, 'new'), [data]);
27:   const sale = useMemo(() => mapCards(data?.discounted_products, 'sale'), [data]);
28:   const hasProducts = best.length + latest.length + sale.length > 0;
29: 
30:   return <>
31:     <SophieHero slides={slides} isLoading={isPending} />
32:     {isPending && <SophieProductsSection title="BEST SELLERS" subtitle="" products={[]} isLoading />}
33:     {!isPending && isError && !data && <SophieSectionError onRetry={() => { void refetch(); }} />}
34:     {!isPending && data && !hasProducts && <SophieComingSoon />}
35:     {!isPending && data && <SophieProductsSection id="best-sellers" title="BEST SELLERS" subtitle="Our most-loved pieces, chosen by you." products={best} showViewMore viewMoreHref={STORE_ROUTES.shop({ sort: 'best_selling' })} />}
36:     {!isPending && <SophiePromoBanners banners={promos} />}
37:     {!isPending && data && <>
38:       <SophieProductsSection id="new-arrivals" title="NEW ARRIVALS" subtitle="Fresh silhouettes, just landed." products={latest} showViewMore viewMoreHref={STORE_ROUTES.shop({ sort: 'newest' })} className="pt-12 pb-10" />
39:       <SophieProductsSection id="on-sale" title="ON SALE" subtitle="Limited-time prices on selected styles." products={sale} showViewMore viewMoreHref={STORE_ROUTES.shop({ on_sale: '1' })} className="pt-12 pb-20" />
40:     </>}
41:     {!isPending && popup && <SophiePopup key={`${popup.id}:${popup.image}`} banner={popup} />}
42:     <SophieFooter />
43:   </>;
