 31: export function SophieMegaDropdown({
 32:   isOpen = false,
 33:   onClose,
 34:   defaultDept = null,
 35:   onSelectCategory,
 36:   onAddToCart,
 37:   onGoToCheckout,
 38:   departments = null,
