 43:   const router = useRouter();
 44:   const deptKeys = departments ? Object.keys(departments) : [];
 45:   const [activeDeptKey, setActiveDeptKey] = useState(defaultDept ?? deptKeys[0] ?? null);
 46:   const menuRef = useRef(null);
