  3: import React, { useState, useEffect, useRef } from 'react';
  4: const FALLBACK_USER = {
  5:   name: 'My account',
  6:   initials: 'MA',
  7:   email: '',
  8:   role: 'Member',
  9:   avatar: null,
 10:   walletBalance: null,
 11:   menuItems: [
 12:     { id: 'profile', label: 'My profile', icon: 'fa-regular fa-user', type: 'item' },
 13:     { id: 'signout', label: 'Sign out', icon: 'fa-solid fa-arrow-from-bracket', isSignOut: true, type: 'item' },
 14:   ],
 15: };
 16: import { formatStorePrice } from '@alfarid/utils';
 17: import { StoreImage } from '../StoreImage';
 18: 
 19: /**
 20:  * SophieProfileDropdown Component
 21:  *
 22:  * Luxury avatar + dropdown card with account links.
 23:  * - No avatar image: circle with the user's initials.
 24:  * - Promo ribbon renders only when `user.ribbonText` is set (storefront never sends one).
 25:  * - Wallet line renders only when `user.walletBalance` is present, formatted via formatStorePrice (EGP).
 26:  * - Keyboard: ArrowUp/ArrowDown move between items, Escape closes and refocuses the trigger.
 27:  *
 28:  * @param {Object} props
 29:  * @param {Object} [props.user] User data override (profile VM from toProfileVM)
 30:  * @param {Function} [props.onSelectAction] Callback when an item is clicked: (actionId) => void
 31:  * @param {Function} [props.onApplyPromo] Callback when ribbon is clicked: (promoCode) => void
 32:  * @param {string} [props.className] Additional CSS class
 33:  */
 34: export function SophieProfileDropdown({
 35:   user = FALLBACK_USER,
 36:   onSelectAction,
 37:   onApplyPromo,
 38:   className = ''
 39: }) {
 40:   const [isOpen, setIsOpen] = useState(false);
 41:   const containerRef = useRef(null);
 42:   const triggerRef = useRef(null);
 43:   const itemRefs = useRef([]);
 44: 
 45:   const actionableItems = (user.menuItems ?? []).filter((item) => item.type !== 'divider');
 46:   const initials = user.initials
 47:     || String(user.name ?? '?').split(' ').filter(Boolean).slice(0, 2).map((w) => w[0]).join('').toUpperCase()
 48:     || '?';
 49:   const walletNumber = user.walletBalance === null || user.walletBalance === undefined || user.walletBalance === ''
 50:     ? null
 51:     : Number(user.walletBalance);
 52:   const showWallet = walletNumber !== null && Number.isFinite(walletNumber);
 53: 
 54:   // Close when clicking outside; Escape closes
 55:   useEffect(() => {
 56:     function handleClickOutside(event) {
 57:       if (containerRef.current && !containerRef.current.contains(event.target)) {
 58:         setIsOpen(false);
 59:       }
 60:     }
 61: 
 62:     function handleKeyDown(event) {
 63:       if (event.key === 'Escape') {
 64:         setIsOpen(false);
 65:       }
 66:     }
 67: 
 68:     if (isOpen) {
 69:       document.addEventListener('mousedown', handleClickOutside);
 70:       document.addEventListener('keydown', handleKeyDown);
 71:     }
 72:     return () => {
 73:       document.removeEventListener('mousedown', handleClickOutside);
 74:       document.removeEventListener('keydown', handleKeyDown);
 75:     };
 76:   }, [isOpen]);
 77: 
 78:   // Return focus to the trigger after closing via Escape
 79:   useEffect(() => {
 80:     if (!isOpen && document.activeElement && containerRef.current?.contains(document.activeElement)) {
 81:       triggerRef.current?.focus();
 82:     }
 83:   }, [isOpen]);
 84: 
 85:   const focusItem = (index) => {
 86:     const el = itemRefs.current[index];
 87:     if (el) el.focus();
 88:   };
 89: 
 90:   const handleMenuKeyDown = (event, index) => {
 91:     if (event.key === 'ArrowDown') {
 92:       event.preventDefault();
 93:       focusItem((index + 1) % actionableItems.length);
 94:     } else if (event.key === 'ArrowUp') {
 95:       event.preventDefault();
 96:       focusItem((index - 1 + actionableItems.length) % actionableItems.length);
 97:     } else if (event.key === 'Home') {
 98:       event.preventDefault();
 99:       focusItem(0);
100:     } else if (event.key === 'End') {
101:       event.preventDefault();
102:       focusItem(actionableItems.length - 1);
103:     }
104:   };
105: 
106:   const handleToggle = (e) => {
107:     e.stopPropagation();
108:     setIsOpen((prev) => !prev);
109:   };
110: 
111:   const handleRibbonClick = (e) => {
112:     e.stopPropagation();
113:     setIsOpen(false);
114:     if (onApplyPromo) {
115:       if (user.promoCode) onApplyPromo(user.promoCode);
116:     } else if (onSelectAction) {
117:       onSelectAction('ribbon');
118:     }
119:   };
120: 
121:   const handleItemClick = (item) => {
122:     setIsOpen(false);
123:     if (onSelectAction) {
124:       onSelectAction(item.id);
125:     }
126:   };
127: 
128:   let actionIndex = -1;
129: 
130:   return (
131:     <div
132:       ref={containerRef}
133:       className={`profile-menu-wrap ${isOpen ? 'is-open' : ''} ${className}`}
134:       id="profile-menu-wrap"
135:     >
136:       {/* Avatar Button Trigger */}
137:       <button
138:         type="button"
139:         ref={triggerRef}
140:         className="profile-avatar-btn"
141:         id="profile-trigger-btn"
142:         onClick={handleToggle}
143:         onKeyDown={(event) => {
144:           if (event.key !== 'ArrowDown' && event.key !== 'ArrowUp') return;
145:           event.preventDefault();
