150:         aria-haspopup="menu"
151:         aria-expanded={isOpen}
152:         title={`${user.name} (${user.role})`}
153:       >
154:         <span className="profile-avatar-inner">
155:           {user.avatar ? (
156:             <StoreImage src={user.avatar} alt={user.name} />
157:           ) : (
158:             <span className="text-white text-xs font-semibold" aria-hidden="true">
159:               {initials}
160:             </span>
161:           )}
162:         </span>
163:       </button>
164: 
165:       {/* Floating Profile Card */}
166:       <div
167:         className="profile-dropdown-card"
168:         id="profile-dropdown"
169:         role="menu"
170:         inert={!isOpen}
171:         aria-hidden={!isOpen}
172:         onBlur={(event) => { if (!containerRef.current?.contains(event.relatedTarget)) setIsOpen(false); }}
173:         aria-label="Profile Menu"
174:       >
175:         {/* Account identity header */}
176:         <div className="profile-identity">
177:           <p className="profile-identity-name">{user.name}</p>
178:           {user.email ? <p className="profile-identity-email">{user.email}</p> : null}
179:           {showWallet ? <p className="profile-identity-wallet">Wallet: {formatStorePrice(walletNumber)}</p> : null}
180:         </div>
181: 
182:         {/* Promotional ribbon: only when explicitly provided (never for storefront accounts) */}
183:         {user.ribbonText && (
184:           <div className="profile-ribbon-wrap">
185:             <button
186:               type="button"
187:               className="profile-ribbon"
188:               id="profile-ribbon-btn"
189:               onClick={handleRibbonClick}
190:               title={`Click to apply ${user.ribbonText} promo code!`}
191:             >
192:               {user.ribbonText}
193:             </button>
194:           </div>
195:         )}
196: 
197:         {/* Menu Items List */}
198:         <div className="profile-menu-list">
199:           {user.menuItems?.map((item) => {
200:             if (item.type === 'divider') {
201:               return <div key={item.id} className="profile-menu-divider" role="separator" />;
202:             }
203: 
204:             actionIndex += 1;
205:             const currentIndex = actionIndex;
206:             const itemClasses = [
207:               'profile-menu-item',
208:               item.highlighted ? 'highlighted' : '',
209:               item.isSignOut ? 'sign-out' : ''
210:             ]
211:               .filter(Boolean)
212:               .join(' ');
213: 
214:             return (
215:               <button
216:                 key={item.id}
217:                 ref={(el) => { itemRefs.current[currentIndex] = el; }}
218:                 type="button"
219:                 className={itemClasses}
220:                 onClick={() => handleItemClick(item)}
221:                 onKeyDown={(e) => handleMenuKeyDown(e, currentIndex)}
222:                 role="menuitem"
223:               >
224:                 <i className={item.icon} aria-hidden="true" />
225:                 <span>{item.label}</span>
