 9: export function BrandingProvider({ children, loadBranding, initialBranding = DEFAULT_BRANDING, titleSuffix = '', manageHead = true, pollIntervalMs = 60_000 }: {
10:   children: ReactNode;
11:   loadBranding: (signal?: AbortSignal) => Promise<BrandIdentity>;
12:   initialBranding?: BrandIdentity;
13:   titleSuffix?: string;
14:   manageHead?: boolean;
15:   pollIntervalMs?: number;
16: }) {
17:   const [branding, setBranding] = useState(initialBranding);
18:   const controller = useRef<AbortController | null>(null);
19:   const pending = useRef<Promise<void> | null>(null);
20:   const lastAttempt = useRef(-Infinity);
21:   const refresh = useCallback(async (force = false): Promise<void> => {
22:     if (pending.current && !controller.current?.signal.aborted) {
23:       await pending.current;
24:       if (force) await refresh(true);
25:       return;
26:     }
27:     if (!force && !controller.current?.signal.aborted && Date.now() - lastAttempt.current < 30_000) return;
28:     lastAttempt.current = Date.now();
29:     const requestController = new AbortController();
30:     controller.current = requestController;
31:     const request = (async () => {
32:       try {
33:         const next = await loadBranding(requestController.signal);
34:         if (!requestController.signal.aborted) setBranding({ ...DEFAULT_BRANDING, ...next, name: next.name?.trim() || DEFAULT_BRANDING.name });
35:       } catch (error) {
36:         if (!requestController.signal.aborted) console.warn('Brand identity update failed; keeping the last known identity.', error instanceof Error ? error.message : 'Unknown error');
37:       }
38:     })();
39:     pending.current = request;
40:     await request;
41:     if (pending.current === request) pending.current = null;
42:   }, [loadBranding]);
43:   const refreshBranding = useCallback(() => refresh(true), [refresh]);
44: 
45:   useEffect(() => {
46:     void refresh();
47:     const refreshVisible = () => { if (document.visibilityState === 'visible') void refresh(); };
48:     const timer = pollIntervalMs > 0 ? setInterval(refreshVisible, pollIntervalMs) : null;
49:     window.addEventListener('focus', refreshVisible);
50:     document.addEventListener('visibilitychange', refreshVisible);
51:     return () => {
52:       controller.current?.abort();
53:       if (timer !== null) clearInterval(timer);
54:       window.removeEventListener('focus', refreshVisible);
55:       document.removeEventListener('visibilitychange', refreshVisible);
56:     };
57:   }, [refresh, pollIntervalMs]);
58: 
59:   useEffect(() => {
60:     if (manageHead) document.title = titleSuffix ? `${branding.name} | ${titleSuffix}` : branding.name;
61:   }, [branding.name, titleSuffix, manageHead]);
62: 
63:   useEffect(() => {
64:     if (!manageHead) return;
65:     const existing = document.head.querySelector<HTMLLinkElement>('link[data-brand-icon]');
66:     if (!branding.logo) { existing?.remove(); return; }
67:     const favicon = existing ?? document.createElement('link');
