 16: export function CategoriesContent() {
 17:   const sp = useSearchParams();
 18:   const router = useRouter();
 19:   const pathname = usePathname();
 20:   const filters = useMemo(() => parseFilters(new URLSearchParams(sp.toString())), [sp]);
 21:   const productSlug = sp.get('product');
 22:   const activeView: 'catalog' | 'detail' = productSlug ? 'detail' : 'catalog';
 23: 
 24:   const updateFilters = (patch: Partial<CatalogFilterState>) =>
 25:     router.replace(`${pathname}${buildSearch({ ...filters, ...patch })}`, { scroll: false });
 26:   const resetFilters = () => router.replace(pathname, { scroll: false });
 27:   const openProduct = (slug: string) => {
 28:     router.push(`${pathname}${buildSearch(filters, { product: slug })}`);
 29:     window.scrollTo({ top: 0, behavior: 'smooth' });
 30:   };
 31:   const closeProduct = () => router.push(`${pathname}${buildSearch(filters)}`, { scroll: false });
 32: 
 33:   // UI state (kept local)
 34:   const [isSidebarOpen, setIsSidebarOpen] = useState<boolean>(true);
 35:   const [toast, setToast] = useState<{ show: boolean; msg: string }>({ show: false, msg: '' });
 36:   const [wishlist, setWishlist] = useState<Set<number>>(new Set());
 37: 
 38:   useEffect(() => {
 39:     try {
 40:       const raw = localStorage.getItem('sophie_wishlist');
 41:       if (raw) setWishlist(new Set(JSON.parse(raw) as number[]));
 42:     } catch { /* storage unavailable */ }
 43:   }, []);
 44: 
 45:   const showToast = (msg: string) => {
 46:     setToast({ show: true, msg });
 47:     setTimeout(() => {
 48:       setToast({ show: false, msg: '' });
 49:     }, 3200);
 50:   };
 51: 
 52:   // Queries
 53:   const categoriesQ = useStoreCategories();
 54:   const facetsQ = useCatalogFilters(toFacetParams(filters));
 55:   const productsQ = useStoreProducts(toApiParams(filters));
 56:   const productQ = useStoreProduct(productSlug);
 57:   const similarQ = useSimilarProducts(productSlug);
 58: 
 59:   const cards = useMemo(() => (productsQ.data?.pages ?? []).flatMap((p) => p.data).map(toCardVM), [productsQ.data]);
 60:   const total = productsQ.data?.pages[0]?.meta.total ?? 0;
 61:   const roots = categoriesQ.data ?? [];
 62:   const allCount = roots.reduce((t, c) => t + c.products_count, 0);
 63:   const activeCat = findCategory(roots, filters.category);
 64: 
 65:   const handleToggleWishlist = (productId: number, e: React.MouseEvent) => {
 66:     e.stopPropagation();
 67:     setWishlist((prev) => {
 68:       const next = new Set(prev);
 69:       if (next.has(productId)) {
 70:         next.delete(productId);
 71:         showToast('Removed from your wishlist.');
 72:       } else {
 73:         next.add(productId);
 74:         showToast('Saved to your wishlist!');
 75:       }
 76:       try { localStorage.setItem('sophie_wishlist', JSON.stringify([...next])); } catch { /* storage unavailable */ }
 77:       return next;
 78:     });
 79:   };
 80: 
 81:   const toggleOccasion = (id: StoreOccasion) => {
 82:     const next = filters.occasions.includes(id)
 83:       ? filters.occasions.filter((o) => o !== id)
 84:       : [...filters.occasions, id];
 85:     updateFilters({ occasions: next });
 86:   };
 87: 
 88:   const toggleColor = (id: string) => updateFilters({ color: filters.color === id ? null : id });
 89: 
 90:   const renderCard = (card: CatalogCardVM) => {
 91:     const isWishlisted = wishlist.has(card.id);
 92:     return (
 93:       <div key={card.id} className="product-card" onClick={() => openProduct(card.slug)}>
 94:         <div className="product-img-box">
 95:           {card.badge && <span className={card.badgeType}>{card.badge}</span>}
 96:           <div className="card-actions">
 97:             <span
 98:               className="action-btn" title="Choose options"
 99:               onClick={(e) => {
100:                 e.stopPropagation();
101:                 openProduct(card.slug);
102:               }}
103:             >
104:               <i className="fa-solid fa-bag-shopping" />
105:             </span>
106:             <span className="action-btn" title="Quick View" onClick={(e) => { e.stopPropagation(); openProduct(card.slug); }}>
107:               <i className="fa-regular fa-eye" />
108:             </span>
109:             <span className="action-btn" title="Add to Wishlist" onClick={(e) => handleToggleWishlist(card.id, e)}>
110:               <i className={isWishlisted ? 'fa-solid fa-heart' : 'fa-regular fa-heart'} style={{ color: isWishlisted ? '#e11d48' : '' }} />
111:             </span>
112:           </div>
113:           <StoreImage src={card.img ?? DEFAULT_HERO.img} className="" alt={card.name} loading="lazy" />
114:         </div>
115:         <p className="product-category-tag">{card.categoryLabel}</p>
116:         <h3 className="product-name">{card.name}</h3>
117:         <p className="product-price">
118:           {card.oldPriceLabel && <span className="old-price">{card.oldPriceLabel}</span>}
