128:       {(similarQ.data ?? []).length > 0 && <section className="categories-container related-section"><h2 className="related-title">YOU MAY ALSO ADORE</h2><div className="product-grid">{(similarQ.data ?? []).slice(0, 4).map(toCardVM).map(renderCard)}</div></section>}
129:     </>;
130:   }
131: 
132:   const heroTitle = activeCat ? { light: 'SHOP', bold: pick(activeCat.node.name_en, activeCat.node.name_ar).toUpperCase() } : { light: DEFAULT_HERO.light, bold: DEFAULT_HERO.bold };
133:   const heroDesc = activeCat ? (pick(activeCat.node.description_en, activeCat.node.description_ar) || DEFAULT_HERO.desc) : DEFAULT_HERO.desc;
134:   const heroImg = activeCat?.node.image ?? DEFAULT_HERO.img;
135: 
