170:         </div>
171:       </div>}
172: 
173:       {/* ================= CATALOG CONTENT ================= */}
174:       <section className="catalog-section">
175:         <div className="categories-container">
176:           {activeView === 'catalog' ? (
177:             /* ================= VIEW 1: CATALOG GRID ================= */
178:             <div className="catalog-view">
179:               {/* Toolbar */}
180:               <div className="catalog-toolbar">
181:                 <div className="toolbar-left">
182:                   <button
183:                     className={`btn-filter-toggle ${isSidebarOpen ? '' : 'open'}`}
184:                     onClick={() => setIsSidebarOpen(!isSidebarOpen)}
185:                     aria-controls="catalog-filters"
186:                     aria-expanded={isSidebarOpen}
187:                   >
188:                     <i className="fa-solid fa-sliders" />
189:                     <span>{isSidebarOpen ? 'Hide Filters' : 'Show Filters'}</span>
190:                   </button>
191:                   <span className="filter-count-badge">
192:                     Showing {total} pieces
193:                   </span>
194:                 </div>
195: 
196:                 {/* Quick Category Pills */}
197:                 <div className="category-pills">
198:                   <button
199:                     className={`cat-pill ${filters.category === null ? 'active' : ''}`}
200:                     onClick={() => updateFilters({ category: null })}
201:                   >
202:                     All Bags
203:                   </button>
204:                   {roots.map((c) => (
205:                     <button
206:                       key={c.slug}
