354:                               <input type="radio" name="priceRange" value={r.id} checked={isActive} readOnly />
355:                               <span className="custom-box">{isActive ? '✓' : ''}</span>
356:                               <span>{priceRangeLabel(r)} <span className="count">{r.count}</span></span>
357:                             </label>
358:                           );
359:                         })}
360:                       </div>
361:                     </div>
362:                   </div>
363:                 </aside>
364: 
365:                 {/* Product Grid */}
366:                 <div className="catalog-main">
