 16: export function DesignShowcaseContent() {
 17:   const router = useRouter();
 18:   // Browsing modes; every product opens the shared purchase stage.
 19:   const [currentMode, setCurrentMode] = useState<'carousel' | 'grid'>('carousel');
 20:   const [activeIndex, setActiveIndex] = useState<number>(0);
 21:   const [activeVariantId, setActiveVariantId] = useState<number | null>(null);
 22:   const [activeCategoryIndex, setActiveCategoryIndex] = useState<number>(0);
 23: 
 24:   // Carousel Animation & Scroll Lock Ref
 25:   const isScrollLocked = useRef<boolean>(false);
 26:   const [isInfoFading, setIsInfoFading] = useState<boolean>(false);
 27: 
 28:   // Data
 29:   const showcaseQ = useStoreShowcase();
 30:   const items = useMemo(() => (showcaseQ.data ?? []).map(toDetailVM), [showcaseQ.data]);
 31:   const gridQ = useStoreProducts({ sort: 'featured', per_page: 12 });
 32:   const gridCards = useMemo(() => (gridQ.data?.pages[0]?.data ?? []).map(toCardVM), [gridQ.data]);
 33:   const categoriesQ = useStoreCategories();
 34:   const roots = categoriesQ.data ?? [];
 35:   const totalProducts = items.length;
 36:   const current = items[activeIndex] ?? null;
 37:   const canNav = totalProducts > 1;
 38: 
 39:   useEffect(() => {
 40:     if (activeCategoryIndex > roots.length - 1) setActiveCategoryIndex(0);
 41:   }, [roots.length, activeCategoryIndex]);
 42: 
 43:   useEffect(() => {
 44:     if (totalProducts === 0) {
 45:       setActiveIndex(0);
 46:       setActiveVariantId(null);
 47:       return;
 48:     }
 49:     if (activeIndex >= totalProducts) { setActiveIndex(0); return; }
 50:     const cur = items[activeIndex];
 51:     if (cur) setActiveVariantId((cur.variants.find((v) => v.inStock) ?? cur.variants[0])?.id ?? null);
 52:   }, [activeIndex, items, totalProducts]);
 53: 
 54:   const variant = current?.variants.find((v) => v.id === activeVariantId) ?? current?.variants[0] ?? null;
 55:   const activeRoot = roots[activeCategoryIndex] ?? null;
 56: 
 57: 
 58:   // Navigate Carousel
 59:   const navigateCarousel = useCallback(
 60:     (direction: number) => {
 61:       if (totalProducts <= 1) return;
 62:       setIsInfoFading(true);
 63:       setActiveIndex((prev) => (prev + direction + totalProducts) % totalProducts);
 64:       setTimeout(() => {
 65:         setIsInfoFading(false);
 66:       }, 220);
 67:     },
 68:     [totalProducts]
 69:   );
 70: 
 71:   const selectSlide = (index: number) => {
 72:     if (totalProducts === 0) return;
 73:     if (index === activeIndex) {
 74:       openDetails();
 75:       return;
 76:     }
 77:     setIsInfoFading(true);
 78:     setActiveIndex(index);
 79:     setTimeout(() => {
 80:       setIsInfoFading(false);
 81:     }, 220);
 82:   };
 83: 
 84:   const openDetails = () => {
 85:     const item = items[activeIndex];
 86:     if (item) router.push(STORE_ROUTES.product(item.slug));
 87:   };
 88: 
 89:   const switchMode = (mode: 'carousel' | 'grid') => {
 90:     setCurrentMode(mode);
 91:     if (typeof window !== 'undefined') {
 92:       window.scrollTo({ top: 0, behavior: 'smooth' });
 93:     }
 94:   };
 95: 
 96:   // Keyboard navigation
 97:   useEffect(() => {
 98:     const handleKeyDown = (e: KeyboardEvent) => {
 99:       if (currentMode !== 'carousel' || !canNav) return;
100:       if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
101:         navigateCarousel(1);
102:       } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
103:         navigateCarousel(-1);
104:       }
105:     };
106: 
107:     window.addEventListener('keydown', handleKeyDown);
108:     return () => window.removeEventListener('keydown', handleKeyDown);
109:   }, [currentMode, navigateCarousel, canNav]);
110: 
111:   // Mouse wheel scroll navigation for 3D stage
112:   useEffect(() => {
113:     const handleWheel = (e: WheelEvent) => {
114:       if (currentMode !== 'carousel' || !canNav) return;
115:       if (isScrollLocked.current) return;
116: 
117:       if (Math.abs(e.deltaY) > 25) {
118:         isScrollLocked.current = true;
119:         if (e.deltaY > 0) {
120:           navigateCarousel(1);
121:         } else {
122:           navigateCarousel(-1);
123:         }
124: 
125:         setTimeout(() => {
126:           isScrollLocked.current = false;
127:         }, 550);
128:       }
129:     };
130: 
131:     window.addEventListener('wheel', handleWheel, { passive: true });
132:     return () => window.removeEventListener('wheel', handleWheel);
133:   }, [currentMode, navigateCarousel, canNav]);
134: 
135:   // Touch Swipe for Mobile / Tablets
136:   const touchCoords = useRef<{ x: number; y: number }>({ x: 0, y: 0 });
137:   const handleTouchStart = (e: React.TouchEvent) => {
138:     touchCoords.current = {
139:       x: e.touches[0].clientX,
140:       y: e.touches[0].clientY,
141:     };
142:   };
143: 
144:   const handleTouchEnd = (e: React.TouchEvent) => {
145:     if (currentMode !== 'carousel' || !canNav) return;
146:     const diffX = touchCoords.current.x - e.changedTouches[0].clientX;
147:     const diffY = touchCoords.current.y - e.changedTouches[0].clientY;
148: 
149:     if (Math.abs(diffX) > 40 && Math.abs(diffX) > Math.abs(diffY)) {
150:       if (diffX > 0) navigateCarousel(1);
151:       else navigateCarousel(-1);
152:     }
153:   };
154: 
155:   const handleGridCard = (card: CatalogCardVM) => {
156:     router.push(STORE_ROUTES.product(card.slug));
157:   };
158: 
159:   // 3D stage slots indices
160:   const leftIdx = totalProducts > 0 ? (activeIndex - 1 + totalProducts) % totalProducts : 0;
161:   const rightIdx = totalProducts > 0 ? (activeIndex + 1) % totalProducts : 0;
162: 
163:   const leftItem = items[leftIdx] ?? null;
164:   const rightItem = items[rightIdx] ?? null;
165:   const centerImg = variant?.images[0]?.url ?? current?.images[0]?.url ?? null;
166: 
167:   const brand = current && current.categoryLabel ? current.categoryLabel.toUpperCase() : 'SOPHIE';
168:   const priceLabel = current ? (variant?.price ?? current.fallbackPrice) : null;
169:   return (
170:     <div className="design-page" onTouchStart={handleTouchStart} onTouchEnd={handleTouchEnd}>
171:       {/* ================= VIEW SWITCHER BUTTONS (TOP RIGHT) ================= */}
172:       <div className="design-view-switcher">
173:         <button
174:           className={`design-switch-btn ${currentMode === 'carousel' ? 'active' : ''}`}
175:           onClick={() => switchMode('carousel')}
176:           title="3D Carousel"
177:         >
178:           <i className="fa-solid fa-cube" /> <span>3D Stage</span>
179:         </button>
180:         <button
181:           className={`design-switch-btn ${currentMode === 'grid' ? 'active' : ''}`}
182:           onClick={() => switchMode('grid')}
183:           title="Catalog Grid"
184:         >
185:           <i className="fa-solid fa-table-cells-large" /> <span>Grid</span>
186:         </button>
187:       </div>
188: 
189:       {/* ================= LEFT SIDEBAR ================= */}
190:       <aside className={`design-sidebar ${currentMode === 'grid' ? 'expanded-subcats' : ''}`}>
191:         <div className="design-sidebar-tag">{'// SOPHIE ATELIER'}</div>
192:         <ul className="design-cat-list">
193:           {roots.map((cat, idx) => (
194:             <li
195:               key={cat.slug}
196:               className={`design-cat-item ${activeCategoryIndex === idx ? 'active' : ''}`}
197:               onClick={() => {
198:                 if (idx === activeCategoryIndex) {
199:                   router.push(STORE_ROUTES.shop({ category: cat.slug }));
200:                 } else {
201:                   setActiveCategoryIndex(idx);
202:                   if (totalProducts > 0) selectSlide(idx % totalProducts);
203:                   if (currentMode === 'grid') switchMode('carousel');
204:                 }
205:               }}
206:             >
207:               {pick(cat.name_en, cat.name_ar).toUpperCase()}
208:             </li>
209:           ))}
210:         </ul>
211:         {(activeRoot?.children ?? []).length > 0 && (
212:           <ul className="design-subcat-list">
213:             {(activeRoot?.children ?? []).map((sub) => (
214:               <li
215:                 key={sub.slug}
216:                 className="design-subcat-item"
217:                 onClick={() => router.push(STORE_ROUTES.shop({ category: sub.slug }))}
218:               >
219:                 {pick(sub.name_en, sub.name_ar)}
220:               </li>
221:             ))}
222:           </ul>
223:         )}
224:       </aside>
225: 
226:       {/* ================= 1. 3D CAROUSEL VIEW ================= */}
227:       {currentMode === 'carousel' && (
228:         <main className="design-carousel-view">
229:           {showcaseQ.isPending ? (
230:             <>
231:               <div className="design-stage">
232:                 {['left', 'center', 'right'].map((pos) => (
233:                   <div key={pos} className={`design-bag-slot ${pos}`}>
234:                     <div className="design-slot-shimmer" />
235:                     <div className="design-bag-shadow" />
236:                   </div>
237:                 ))}
238:               </div>
239:               <div className="design-carousel-info">
240:                 <h1 className="design-brand-title">SOPHIE</h1>
241:                 <p className="design-bag-subtitle">Curating the showcase…</p>
242:               </div>
243:             </>
244:           ) : showcaseQ.isError ? (
245:             <div className="design-carousel-info">
246:               <h1 className="design-brand-title">SOPHIE</h1>
247:               <p className="design-bag-subtitle">Couldn&apos;t load the showcase.</p>
248:               <button className="design-btn-pill" onClick={() => showcaseQ.refetch()}>
249:                 <span>RETRY</span>
250:                 <i className="fa-solid fa-arrow-right" />
251:               </button>
252:             </div>
253:           ) : totalProducts === 0 ? (
254:             <div className="design-carousel-info">
255:               <h1 className="design-brand-title">SOPHIE</h1>
256:               <p className="design-bag-subtitle">Showcase coming soon.</p>
257:               <Link className="design-btn-pill" href="/shop">
258:                 <span>SHOP THE COLLECTION</span>
259:                 <i className="fa-solid fa-arrow-right" />
260:               </Link>
261:             </div>
262:           ) : (
263:             <>
264:               <ShowcaseStage
265:                 previous={{ url: slotImg(leftItem), alt: leftItem?.name ?? 'Previous bag' }}
266:                 current={{ url: centerImg, alt: current?.name ?? 'Selected bag' }}
267:                 next={{ url: slotImg(rightItem), alt: rightItem?.name ?? 'Next bag' }}
268:                 canNavigate={canNav} onNavigate={navigateCarousel} onExplore={openDetails}
269:               />
270: 
271:               {/* Product Details Label & Action */}
272:               {current && (
273:                 <div className={`design-carousel-info ${isInfoFading ? 'fade-out' : ''}`}>
274:                   <h1 className="design-brand-title">{brand}</h1>
275:                   <p className="design-bag-subtitle">
276:                     {current.name} &nbsp;|&nbsp; {priceLabel !== null ? formatStorePrice(priceLabel) : '—'}
277:                   </p>
278:                   <button className="design-btn-pill" onClick={openDetails}>
279:                     <span>EXPLORE DETAILS</span>
280:                     <i className="fa-solid fa-arrow-right" />
281:                   </button>
282:                 </div>
283:               )}
284: 
285:               {/* Scroll Hint */}
286:               {canNav && (
287:                 <div className="design-scroll-hint">
288:                   <i className="fa-solid fa-arrow-down" /> Scroll Mouse Wheel / Swipe to Browse
289:                 </div>
290:               )}
291:             </>
292:           )}
293:         </main>
294:       )}
295: 
296:       {/* ================= 3. GRID CATALOG VIEW ================= */}
297:       {currentMode === 'grid' && (
298:         <section className="design-grid-view active">
299:           <div className="design-products-grid">
300:             {gridQ.isPending ? (
301:               <p className="design-bag-subtitle">Loading the collection…</p>
302:             ) : gridQ.isError ? (
303:               <div className="design-carousel-info">
304:                 <p className="design-bag-subtitle">Couldn&apos;t load the collection.</p>
305:                 <button className="design-btn-pill" onClick={() => gridQ.refetch()}>
306:                   <span>RETRY</span>
307:                   <i className="fa-solid fa-arrow-right" />
308:                 </button>
309:               </div>
310:             ) : (
311:               gridCards.map((card) => (
312:                 <div key={card.id} className="design-grid-card" onClick={() => handleGridCard(card)}>
313:                   <div className="design-grid-img-box">
314:                     {card.badge && <span className="design-grid-card-badge">{card.badge}</span>}
315:                     <StoreImage src={card.img ?? ''} className="" alt={card.name} loading="lazy" />
