  9: interface SophieCartDrawerProps {
 10:   isOpen: boolean;
 11:   onClose: () => void;
 12: }
 13: 
 14: export function SophieCartDrawer({ isOpen, onClose }: SophieCartDrawerProps) {
 15:   const panel = useRef<HTMLDivElement>(null);
 16:   const close = useRef(onClose);
 17:   close.current = onClose;
 18:   useEffect(() => {
 19:     if (!isOpen) return;
 20:     const previous = document.activeElement as HTMLElement | null;
 21:     const overflow = document.body.style.overflow;
 22:     document.body.style.overflow = 'hidden';
 23:     panel.current?.focus();
 24:     const keys = (event: KeyboardEvent) => {
 25:       if (event.key === 'Escape') { event.preventDefault(); close.current(); }
 26:       if (event.key !== 'Tab') return;
 27:       const targets = Array.from(panel.current?.querySelectorAll<HTMLElement>('button:not(:disabled), a[href], input:not(:disabled), [tabindex="0"]') ?? []).filter(el => el.getClientRects().length > 0);
 28:       const first = targets[0], last = targets[targets.length - 1];
 29:       if (!first) { event.preventDefault(); panel.current?.focus(); return; }
 30:       if (event.shiftKey && (document.activeElement === first || document.activeElement === panel.current)) { event.preventDefault(); last.focus(); }
 31:       else if (!event.shiftKey && (document.activeElement === last || document.activeElement === panel.current)) { event.preventDefault(); first.focus(); }
 32:     };
 33:     const focus = (event: FocusEvent) => { if (!panel.current?.contains(event.target as Node)) panel.current?.focus(); };
 34:     document.addEventListener('keydown', keys);
 35:     document.addEventListener('focusin', focus);
 36:     return () => {
 37:       document.removeEventListener('keydown', keys);
 38:       document.removeEventListener('focusin', focus);
 39:       document.body.style.overflow = overflow;
 40:       previous?.focus();
 41:     };
 42:   }, [isOpen]);
 43:   const { items, removeItem, updateQuantity, clearCart, total, loadCart, busy, loading, error } = useCartStore();
 44:   useEffect(() => { if (isOpen) void loadCart(); }, [isOpen, loadCart]);
 45: 
 46:   if (!isOpen) return null;
 47: 
 48:   return (
 49:     <div className="fixed inset-0 z-50 overflow-hidden">
 50:       {/* Backdrop */}
 51:       <div
 52:         className="fixed inset-0 bg-black/50 transition-opacity backdrop-blur-xs"
 53:         onClick={onClose}
 54:         aria-hidden="true"
 55:       />
 56: 
 57:       <div className="fixed inset-y-0 right-0 max-w-full flex pl-10">
 58:         <div ref={panel} tabIndex={-1} aria-modal="true" role="dialog" aria-label="Shopping cart" className="w-screen max-w-md bg-white shadow-2xl flex flex-col">
 59:           {/* Header */}
 60:           <div className="p-6 border-b border-gray-100 flex items-center justify-between">
 61:             <h2 className="font-['Oswald'] text-xl uppercase tracking-wider font-semibold text-black">
 62:               Shopping Cart ({items.reduce((s, i) => s + i.quantity, 0)})
 63:             </h2>
 64:             <button
 65:               onClick={onClose}
 66:               className="text-gray-400 hover:text-black transition p-1"
 67:               aria-label="Close cart"
 68:             >
 69:               <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
 70:                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
 71:               </svg>
 72:             </button>
 73:           </div>
 74: 
 75:           {/* Items List */}
 76:           <div className="flex-1 overflow-y-auto p-6 space-y-4">
 77:             {loading && <p role="status" className="text-sm">Updating your cart…</p>}
 78:             {error && <div role="alert" className="text-sm text-red-700">{error}<button className="block underline mt-2" onClick={() => { void loadCart(); }}>Try again</button></div>}
 79:             {items.length === 0 ? (
 80:               <div className="h-full flex flex-col items-center justify-center text-center py-12">
 81:                 <div className="w-16 h-16 rounded-full bg-gray-100 flex items-center justify-center mb-4 text-gray-400">
