 11: export function SophieHero({ slides, isLoading = false }: { slides: HeroSlide[]; isLoading?: boolean }) {
 12:   const { branding } = useBranding();
 13:   const [index, setIndex] = useState(0);
 14:   const [failed, setFailed] = useState<Set<string>>(() => new Set());
 15:   const [paused, setPaused] = useState(false);
 16:   const [focused, setFocused] = useState(false);
 17:   const [fallbackFailed, setFallbackFailed] = useState(false);
 18:   const touchStart = useRef<number | null>(null);
 19:   const list = useMemo(() => {
 20:     const healthy = slides.filter((s) => s.kind !== 'banner' || !failed.has(`${s.id}:${s.image}`));
 21:     return healthy.length ? healthy : [FALLBACK_SLIDE];
 22:   }, [slides, failed]);
 23:   const activeIndex = index % list.length;
 24:   const slide = list[activeIndex];
 25:   const advance = (direction: number) => setIndex((current) => (current + direction + list.length) % list.length);
 26: 
 27:   useEffect(() => {
 28:     if (isLoading || paused || focused || list.length < 2 || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
 29:     const timer = setInterval(() => setIndex((current) => (current + 1) % list.length), 6000);
 30:     return () => clearInterval(timer);
 31:   }, [isLoading, paused, focused, list.length]);
 32: 
 33:   useEffect(() => {
 34:     if (isLoading) return;
 35:     const next = list[(activeIndex + 1) % list.length];
 36:     if (next.kind === 'banner') { const image = new Image(); image.src = storeImageUrl(next.image); }
 37:   }, [activeIndex, list, isLoading]);
 38: 
 39:   const fallback = slide.kind === 'fallback';
 40:   const kicker = fallback ? `${branding.name} ${slide.subtitle}` : slide.kicker;
 41:   const headline = fallback ? slide.lightTitle : slide.headline;
 42:   const bold = fallback ? slide.boldTitle : slide.headlineBold;
 43:   const description = fallback ? slide.desc : slide.description;
 44:   const href = fallback ? slide.ctaHref : slide.href;
 45:   const label = fallback ? slide.ctaText : slide.ctaLabel || 'SHOP NOW';
 46:   const hasText = Boolean(kicker || headline || bold || description);
 47:   const external = !fallback && slide.isExternal ? { target: '_blank', rel: 'noopener noreferrer' } : {};
 48: 
 49:   return (
 50:     <div className="hero-wrapper relative overflow-hidden bg-[#dfe5e9]" id="top"
 51:       onMouseEnter={() => setPaused(true)} onMouseLeave={() => setPaused(false)}
 52:       onFocusCapture={() => setFocused(true)} onBlurCapture={(event) => { if (!event.currentTarget.contains(event.relatedTarget)) setFocused(false); }}
 53:       onTouchStart={(event) => { touchStart.current = event.touches.length === 1 ? event.touches[0].clientX : null; }}
 54:       onTouchCancel={() => { touchStart.current = null; }}
 55:       onTouchEnd={(event) => {
 56:         if (touchStart.current !== null && !isLoading && list.length > 1) {
 57:           const delta = touchStart.current - event.changedTouches[0].clientX;
 58:           if (Math.abs(delta) > 50) advance(delta > 0 ? 1 : -1);
 59:         }
 60:         touchStart.current = null;
 61:       }}>
 62:       {!isLoading && fallback && !fallbackFailed && (
 63:         <div className="hero-bg-backdrop" aria-hidden="true">
 64:           <div className="hero-bg-backdrop-img"><StoreImage src={slide.imgUrl} className={`${slide.tintClass} w-full h-full object-cover object-center`} alt="" onError={() => setFallbackFailed(true)} /></div>
 65:           <div className="hero-bg-backdrop-overlay" />
 66:         </div>
 67:       )}
 68:       {!isLoading && !fallback && (
 69:         <div className="absolute inset-0" aria-hidden="true">
 70:           <StoreImage key={`${slide.id}:${slide.image}`} src={slide.image} fetchPriority="high" alt="" className="hero-banner-img" onError={() => setFailed((current) => new Set(current).add(`${slide.id}:${slide.image}`))} />
 71:           {hasText && <div className="hero-banner-overlay" />}
 72:         </div>
 73:       )}
 74:       <div className="max-w-[1140px] mx-auto px-5 relative z-10">
 75:         <section className="sophie-hero-content flex flex-col lg:flex-row items-center justify-between min-h-[450px] pt-2 pb-14 relative" aria-label="Featured collection" aria-busy={isLoading}>
 76:           {isLoading ? (
 77:             <>
 78:               <div className="max-w-[430px] w-full space-y-4 mt-6 lg:mt-0" aria-hidden="true">
 79:                 <div className="sophie-skeleton h-3 w-32" /><div className="sophie-skeleton h-12 w-72 max-w-full" /><div className="sophie-skeleton h-12 w-60" />
 80:                 <div className="sophie-skeleton h-3 w-full" /><div className="sophie-skeleton h-3 w-3/4" /><div className="sophie-skeleton h-10 w-36" />
 81:               </div>
 82:               <div className="sophie-skeleton w-[290px] sm:w-[350px] lg:w-[390px] h-[330px] sm:h-[370px] lg:h-[410px] mt-8 lg:mt-0 lg:mr-10 shrink-0" aria-hidden="true" />
 83:             </>
 84:           ) : (
 85:             <>
 86:               {hasText && (
 87:                 <div className="max-w-[430px] z-10 text-center lg:text-left mt-6 lg:mt-0 break-words">
 88:                   {kicker && <p dir="auto" className="font-['Oswald'] text-[13px] font-medium tracking-[0.6px] uppercase text-[#111] mb-2.5">{kicker}</p>}
 89:                   {(headline || bold) && <h1 dir="auto" className="font-['Oswald'] uppercase leading-[1.02] mb-4.5">
 90:                     {headline && <span className="block text-[44px] sm:text-[54px] font-light tracking-[1px] text-[#111]">{headline}</span>}
 91:                     {bold && <span className="block text-[48px] sm:text-[58px] font-bold tracking-[1px] text-[#111]">{bold}</span>}
 92:                   </h1>}
 93:                   {description && <p dir="auto" className="text-[13.5px] leading-[1.6] text-[#333] mb-7 font-['Poppins']">{description}</p>}
