100:                   {fallbackFailed ? <SophieBagPlaceholder /> : <StoreImage src={slide.imgUrl} className={`${slide.tintClass} w-full h-full object-contain block`} alt={`${slide.lightTitle} ${slide.boldTitle}`} onError={() => setFallbackFailed(true)} />}
101:                 </div>
102:               </div>}
103:             </>
