107:               <span className={`block h-[2px] transition-all duration-300 ${activeIndex === position ? 'w-7 bg-[#111111]' : 'w-5 bg-white/80 hover:bg-white shadow-sm'}`} />
108:             </button>)}
109:           </div>}
110:         </section>
111:       </div>
112:     </div>
113:   );
