 8: export function SophiePopup({ banner }: { banner: StoreBanner }) {
 9:   const [open, setOpen] = useState(false);
10:   const [failed, setFailed] = useState(false);
11:   const dismissed = useRef(false);
12:   const dialog = useRef<HTMLDivElement>(null);
13:   const sessionKey = `sophie-popup-${banner.id}`;
14:   const close = useCallback(() => {
15:     dismissed.current = true;
16:     setOpen(false);
17:     try { sessionStorage.setItem(sessionKey, '1'); } catch { /* Remains dismissed for this mount when storage is blocked. */ }
18:   }, [sessionKey]);
19: 
20:   useEffect(() => {
21:     if (dismissed.current) return;
22:     try { if (sessionStorage.getItem(sessionKey)) return; } catch { /* Storage may be disabled. */ }
23:     let alive = true;
24:     let loaded = false;
25:     let elapsed = false;
26:     const image = new Image();
27:     const show = () => { if (alive && loaded && elapsed && !dismissed.current) setOpen(true); };
28:     image.onload = () => { loaded = true; show(); };
29:     image.onerror = () => { if (alive) setFailed(true); };
30:     image.src = storeImageUrl(banner.image);
31:     const timer = setTimeout(() => { elapsed = true; show(); }, 2500);
32:     return () => { alive = false; clearTimeout(timer); image.onload = null; image.onerror = null; };
33:   }, [banner.image, sessionKey]);
34: 
35:   useEffect(() => {
36:     if (!open || failed) return;
37:     const previousOverflow = document.body.style.overflow;
38:     const previousFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null;
39:     document.body.style.overflow = 'hidden';
40:     dialog.current?.querySelector<HTMLButtonElement>('button')?.focus();
41:     const onKey = (event: KeyboardEvent) => {
42:       if (event.key === 'Escape') { event.preventDefault(); close(); }
43:       if (event.key !== 'Tab') return;
44:       const controls = dialog.current?.querySelectorAll<HTMLElement>('button, a[href]');
45:       if (!controls?.length) return;
46:       const first = controls[0];
47:       const last = controls[controls.length - 1];
48:       if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
49:       else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
50:     };
51:     document.addEventListener('keydown', onKey);
52:     return () => { document.body.style.overflow = previousOverflow; document.removeEventListener('keydown', onKey); previousFocus?.focus(); };
53:   }, [open, failed, close]);
54: 
55:   if (!open || failed) return null;
56:   const image = <StoreImage src={banner.image} alt={banner.title} className="w-full h-full object-cover" onError={() => { setFailed(true); setOpen(false); }} />;
57:   return <div className="fixed inset-0 z-[60] bg-black/50 backdrop-blur-[2px] flex items-center justify-center" onClick={(event) => { if (event.target === event.currentTarget) close(); }}>
58:     <div ref={dialog} role="dialog" aria-modal="true" aria-label={banner.title} className="sophie-pop-in w-[88vw] max-w-[380px] aspect-[4/5] bg-white overflow-hidden relative max-h-[90dvh]">
59:       <button onClick={close} aria-label="Close offer" className="absolute z-10 right-3 top-3 rounded-full bg-white w-8 h-8 flex items-center justify-center text-black">
60:         <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true"><path d="m6 6 12 12M6 18 18 6" /></svg>
61:       </button>
62:       {banner.href ? <a href={banner.href} onClick={close} className="block w-full h-full" {...(banner.is_external ? { target: '_blank', rel: 'noopener noreferrer' } : {})}>{image}</a> : image}
63:     </div>
64:   </div>;
65: }  1: 'use client';
