 26: export function SophieProductCard({ product }: { product: SophieProduct }) {
 27:   const addItem = useCartStore((s) => s.addItem);
 28:   const [added, setAdded] = useState(false);
 29:   const addedTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
 30:   const alive = useRef(true);
 31:   useEffect(() => {
 32:     alive.current = true;
 33:     return () => { alive.current = false; if (addedTimer.current) clearTimeout(addedTimer.current); };
 34:   }, []);
 35:   const [adding, setAdding] = useState(false);
 36:   const busy = useCartStore((s) => s.busy);
 37:   const cartError = useCartStore((s) => s.error);
 38:   const [addFailed, setAddFailed] = useState(false);
 39:   const [failedImage, setFailedImage] = useState<string | null>(null);
 40:   const image = product.imgUrl && failedImage !== product.imgUrl ? (
 41:     <StoreImage src={product.imgUrl} alt={product.name} onError={() => setFailedImage(product.imgUrl)}
 42:       className={`${product.tintClass || ''} max-w-[175px] max-h-[200px] object-contain transition-transform duration-300 group-hover:scale-105 ${product.inStock === false ? 'opacity-60' : ''}`} loading="lazy" />
 43:   ) : <SophieBagPlaceholder />;
 44: 
 45:   const handleAddToCart = async () => {
 46:     if (!product.variantId || busy) return;
 47:     setAdding(true);
 48:     setAddFailed(false);
 49:     const saved = await addItem(product.variantId);
 50:     if (!alive.current) return;
 51:     setAdding(false);
 52:     setAdded(saved);
 53:     setAddFailed(!saved);
 54:     if (addedTimer.current) clearTimeout(addedTimer.current);
 55:     if (saved) addedTimer.current = setTimeout(() => setAdded(false), 1600);
 56:   };
 57: 
 58:   return (
 59:     <div className="product-card text-center group flex flex-col">
 60:       {/* Image Box */}
 61:       <div className="bg-[#f3f4f6] relative h-[260px] flex items-center justify-center p-6 mb-3.5 overflow-hidden transition-all duration-300 group-hover:bg-[#ebeef2]">
 62:         {/* Badge */}
 63:         {product.badge && (
 64:           <span className={`absolute top-0 left-0 ${product.badgeTone === 'sale' ? 'bg-[#111]' : product.badgeTone === 'muted' ? 'bg-[#9ca3af]' : 'bg-[#4f7d86]'} text-white font-['Oswald'] text-[10px] font-medium uppercase px-2.5 py-1 tracking-[0.5px] z-10`}>
 65:             {product.badge}
 66:           </span>
 67:         )}
 68: 
 69:         {/* Product Image */}
 70:         {product.href ? <Link href={product.href} aria-label={product.name} className="flex items-center justify-center w-full h-full">{image}</Link> : image}
 71: 
 72:         {/* Quick Add Overlay on Hover */}
 73:         {product.inStock !== false && product.variantId && <div className="absolute inset-x-0 bottom-0 p-3 bg-gradient-to-t from-black/20 to-transparent opacity-100 lg:opacity-0 lg:group-hover:opacity-100 focus-within:opacity-100 transition-opacity flex items-center justify-center">
 74:           <button
 75:             onClick={handleAddToCart}
 76:             disabled={busy}
 77:             className={`font-['Oswald'] text-[11px] uppercase tracking-wider py-1.5 px-4 rounded-xs shadow-sm transition-all duration-200 ${
 78:               added ? 'bg-emerald-600 text-white' : 'bg-black text-white hover:bg-neutral-800'
 79:             }`}
 80:           >
 81:             {adding ? 'Adding…' : added ? '✓ Added' : '+ Add to Cart'}
 82:           </button>
 83:         </div>}
 84:       </div>
 85: 
 86:       {/* Product Name */}
 87:       <h3 dir="auto" className="font-['Oswald'] text-[13px] font-medium text-[#222] mb-1 tracking-[0.2px] hover:text-[#4f7d88] transition-colors line-clamp-1">
 88:         {product.href ? <Link href={product.href}>{product.name}</Link> : product.name}
 89:       </h3>
 90: 
 91:       {/* Product Price */}
 92:       <p className="font-['Oswald'] text-[14px] font-semibold text-[#111]">
 93:         {product.oldPrice && (
 94:           <span className="text-[#b0b0b0] line-through font-normal mr-1 text-[13px]">
 95:             {formatStorePrice(product.oldPrice)}
 96:           </span>
 97:         )}
 98:         <span>{formatStorePrice(product.price)}</span>
 99:       </p>
100:       {addFailed && cartError && <p role="alert" className="text-xs text-red-700 mt-2">{cartError}</p>}
101:     </div>
102:   );
103: } 1: 'use client';
