21:           {(banner.headline_bold || banner.headline) && <h3 dir="auto" className="font-['Poppins'] text-[24px] sm:text-[27px] text-black leading-[1.15] mb-2.5">{banner.headline}{banner.headline && banner.headline_bold ? ' ' : ''}<strong>{banner.headline_bold}</strong></h3>}
22:           {banner.description && <p dir="auto" className="text-[12px] leading-relaxed text-[#222] mb-3">{banner.description}</p>}
23:           {banner.href && <a href={banner.href} {...external} className="text-[12px] text-[#222] inline-flex items-center gap-1.5 hover:text-[#4f7d88] transition-colors">
