 5: export const getServerBranding = cache(async (): Promise<BrandIdentity> => {
 6:   try {
 7:     const apiUrl = new URL(process.env.API_INTERNAL_URL || process.env.NEXT_PUBLIC_API_URL || 'http://127.0.0.1:8000');
 8:     // Laravel's local server binds IPv4; Node may resolve localhost only to IPv6.
 9:     if (!process.env.API_INTERNAL_URL && apiUrl.hostname === 'localhost') apiUrl.hostname = '127.0.0.1';
10:     // Forward the real client IP so Laravel rate limiters (store-catalog) see
11:     // the shopper, not the Next.js node. Safe: fe_public strips any
12:     // client-supplied X-Forwarded-For before it reaches Next.js.
13:     let clientIp: string | undefined;
14:     try {
15:       const { headers } = await import('next/headers');
16:       const h = await headers();
17:       clientIp = h.get('x-forwarded-for')?.split(',')[0]?.trim() || undefined;
18:     } catch {
19:       clientIp = undefined;
20:     }
21:     const response = await fetch(`${apiUrl.href.replace(/\/$/, '')}/api/v1/store/branding`, {
22:       next: { revalidate: 60, tags: ['branding'] }, signal: AbortSignal.timeout(1500),
23:       headers: { Accept: 'application/json', ...(clientIp ? { 'X-Forwarded-For': clientIp } : {}) },
24:     });
25:     if (!response.ok) throw new Error(`Branding API returned ${response.status}`);
26:     const { data } = await response.json() as { data: BrandIdentity };
27:     return { ...DEFAULT_BRANDING, ...data, name: data.name?.trim() || DEFAULT_BRANDING.name, logo: data.logo ? storeImageUrl(data.logo) : null };
28:   } catch (error) {
29:     console.warn('Server branding unavailable; using the default identity.', error instanceof Error ? error.message : 'Unknown error');
30:     return DEFAULT_BRANDING;
31:   }
