 255:   align-items: center;
 256:   gap: 9px;
 257:   background-color: #000;
 258:   color: #fff;
 259:   font-family: 'Oswald', sans-serif;
 260:   font-size: 12px;
 261:   font-weight: 500;
 262:   letter-spacing: 0.8px;
 263:   text-transform: uppercase;
 264:   padding: 9px 20px;
 265:   border: 1px solid #000;
