 367: /* Sidebar Filters - Ultra Sleek Collapsible Drawer */
 368: .filter-sidebar {
 369:   width: 250px;
 370:   max-width: 250px;
 371:   flex-shrink: 0;
 372:   background-color: #fafbfc;
 373:   border: 1px solid #eee;
 374:   border-radius: 4px;
 375:   padding: 24px 20px;
 376:   box-shadow: 0 4px 15px rgba(0, 0, 0, 0.02);
 377:   overflow: hidden;
 378:   opacity: 1;
 379:   transform: translateX(0);
 380:   transition: width 0.45s cubic-bezier(0.25, 1, 0.5, 1),
 381:               max-width 0.45s cubic-bezier(0.25, 1, 0.5, 1),
 382:               padding 0.45s cubic-bezier(0.25, 1, 0.5, 1),
 383:               margin 0.45s cubic-bezier(0.25, 1, 0.5, 1),
 384:               opacity 0.35s ease,
 385:               transform 0.45s cubic-bezier(0.25, 1, 0.5, 1),
 386:               border-color 0.35s ease;
 387:   will-change: width, opacity, transform;
 388: }
 389: 
 390: .filter-sidebar-inner {
 391:   width: 210px;
 392:   transition: opacity 0.3s ease, transform 0.4s cubic-bezier(0.25, 1, 0.5, 1);
 393:   opacity: 1;
 394:   transform: translateX(0);
 395: }
 396: 
 397: /* Sleek Disappear Animation */
 398: .filter-sidebar.hidden {
 399:   display: block !important;
 400:   width: 0 !important;
 401:   max-width: 0 !important;
 402:   padding-top: 24px !important;
 403:   padding-bottom: 24px !important;
 404:   padding-left: 0 !important;
 405:   padding-right: 0 !important;
 406:   margin-right: -36px !important;
 407:   border-color: transparent !important;
 408:   opacity: 0 !important;
 409:   pointer-events: none !important;
 410:   transform: translateX(-24px) scale(0.98) !important;
 411: }
 412: 
 413: .filter-sidebar.hidden .filter-sidebar-inner {
 414:   opacity: 0 !important;
 415:   transform: translateX(-20px) !important;
 416:   pointer-events: none !important;
 417: }
