 775: /* ================= PRODUCT DETAIL VIEW (PDP) ================= */
 776: .product-detail-view {
 777:   animation: fadeInSlide 0.35s ease;
 778: }
 779: 
 780: @keyframes fadeInSlide {
 781:   from {
 782:     opacity: 0;
 783:     transform: translateY(12px);
 784:   }
 785:   to {
 786:     opacity: 1;
