 554: 
 555: .design-details-view.active {
 556:   display: block;
 557:   opacity: 1;
 558: }
 559: 
 560: .design-details-hero {
 561:   position: relative;
 562:   height: 380px;
 563:   display: flex;
 564:   align-items: center;
 565:   justify-content: center;
 566:   overflow: hidden;
 567:   background: radial-gradient(circle at 50% 50%, #f6f8fa 0%, #ffffff 70%);
 568: }
