 802:   font-weight: 600;
 803:   letter-spacing: 0.5px;
 804:   text-transform: uppercase;
 805:   color: var(--text);
 806: }
 807: 
 808: .design-accordion-header i {
 809:   font-size: 11px;
 810:   color: #999;
