210: /* All authentication forms share the same frame and Birkin artwork. */
211: .luxury-auth-fields { display: flex; flex-direction: column; gap: 20px; min-width: 0; border: 0; margin: 0; padding: 0; }
212: .luxury-auth-fields:disabled { opacity: .7; }
213: .luxury-switch-link { border: 0; padding: 0; background: transparent; cursor: pointer; }
214: .luxury-switch-link:disabled, .luxury-inline-action:disabled { cursor: wait; opacity: .6; }
215: .luxury-field-hint { margin: 8px 0 12px; color: #666; font-size: 12px; line-height: 1.8; }
216: .luxury-inline-action { display: inline-block; border: 0; background: transparent; padding: 8px 0; color: #262626; font-family: var(--auth-sans); font-size: 12px; text-decoration: underline; text-underline-offset: 4px; cursor: pointer; }
217: .luxury-phone-verification { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: end; gap: 12px; margin-top: 10px; }
218: .luxury-secondary-button { min-height: 44px; padding: 10px 16px; border: 1px solid #d4d4d4; border-radius: 999px; background: #fff; color: #262626; font-family: var(--auth-sans); font-size: 13px; cursor: pointer; }
219: .luxury-secondary-button:hover { background: #fafafa; border-color: #737373; }
220: .luxury-secondary-button:disabled { cursor: wait; opacity: .6; }
221: .luxury-success { padding: 12px 16px; border: 1px solid #d4d4d4; border-radius: 12px; color: #262626; background: #fafafa; font-size: 13px; line-height: 1.8; overflow-wrap: anywhere; }
222: .luxury-file-input { display: block; width: 100%; min-width: 0; border: 1px dashed #a3a3a3; border-radius: 12px; padding: 14px; color: #525252; font-size: 12px; }
223: .luxury-file-input::file-selector-button { margin-inline-end: 12px; border: 0; border-radius: 999px; padding: 8px 12px; background: #171717; color: #fff; font: inherit; cursor: pointer; }
224: .luxury-file-list { padding-inline-start: 18px; margin-top: 10px; font-size: 12px; color: #525252; overflow-wrap: anywhere; }
225: .luxury-req-mark { margin-inline-start: 4px; color: #525252; }
226: .luxury-stepper { display: flex; gap: 8px; margin: 0 0 24px; }
227: .luxury-step-pill {
228:   flex: 1; min-width: 0; min-height: 44px; padding: 10px 12px;
229:   border: 1px solid #d4d4d4; border-radius: 12px; background: #fff;
230:   color: #525252; font: inherit; font-size: 13px; line-height: 1.6;
231: }
232: .luxury-step-pill[data-active="true"] { border-color: #171717; background: #171717; color: #fff; }
233: .luxury-step-pill:disabled:not([data-active="true"]) { color: #737373; background: #fafafa; }
234: .luxury-inline-action-row { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
235: .luxury-countdown-badge { color: #525252; font-size: 13px; font-variant-numeric: tabular-nums; }
236: .luxury-verified-badge { color: #166534; font-weight: 600; }
237: .luxury-verified-badge::before { content: '✓'; margin-inline-end: 6px; }
238: .luxury-file-list { list-style: none; padding: 0; }
239: .luxury-file-list li { display: flex; align-items: center; justify-content: space-between; gap: 12px; border-bottom: 1px solid #e5e5e5; }
240: .luxury-file-list li > span { min-width: 0; overflow-wrap: anywhere; }
241: .luxury-file-remove { flex-shrink: 0; min-width: 44px; min-height: 44px; border: 0; background: transparent; color: #b91c1c; cursor: pointer; font-size: 16px; }
242: .luxury-file-picker { position: relative; display: flex; align-items: center; justify-content: center; min-height: 52px; border: 1px dashed #a3a3a3; border-radius: 12px; background: #fafafa; color: #262626; font-size: 14px; }
243: .luxury-file-picker .luxury-file-input { position: absolute; inset: 0; width: 100%; height: 100%; padding: 0; border: 0; opacity: 0; cursor: pointer; }
244: .luxury-file-picker:focus-within { outline: 2px solid #171717; outline-offset: 4px; }
245: .luxury-eye-btn { width: 44px; }
246: .luxury-inline-action { min-height: 44px; }
247: .luxury-title:focus { outline: none; }
248: .luxury-right-col { position: sticky; top: 0; }
