 134: /* Profile Trigger & Dropdown (Screenshot 1 Exact Design) */
 135: .profile-menu-wrap {
 136:   position: relative;
 137:   display: flex;
 138:   align-items: center;
 139: }
 140: 
 141: .profile-avatar-btn {
 142:   width: 38px;
 143:   height: 38px;
 144:   border-radius: 50%;
 145:   padding: 2px;
 146:   background: #ffffff;
 147:   border: 2px solid #f59e0b;
 148:   box-shadow: 0 0 0 2px rgba(245, 158, 11, 0.2);
 149:   cursor: pointer;
 150:   display: inline-flex;
 151:   align-items: center;
 152:   justify-content: center;
 153:   transition: transform 0.2s ease, box-shadow 0.2s ease;
 154:   position: relative;
 155:   overflow: hidden;
 156: }
 157: 
 158: .profile-avatar-btn:hover,
 159: .profile-menu-wrap.is-open .profile-avatar-btn {
