 164: .profile-avatar-inner {
 165:   width: 100%;
 166:   height: 100%;
 167:   border-radius: 50%;
 168:   background: linear-gradient(135deg, #f97316 0%, #fb923c 100%);
 169:   display: flex;
 170:   align-items: center;
 171:   justify-content: center;
 172:   overflow: hidden;
 173: }
 174: 
 175: .profile-avatar-inner img {
 176:   width: 100%;
 177:   height: 100%;
