 182: /* Profile Dropdown Card */
 183: .profile-dropdown-card {
 184:   position: absolute;
 185:   top: calc(100% + 14px);
 186:   right: -8px;
 187:   width: 248px;
 188:   background-color: #ffffff;
 189:   border-radius: 22px;
 190:   border: 1px solid #eef0f3;
 191:   box-shadow: 0 22px 50px rgba(15, 23, 42, 0.13), 0 4px 14px rgba(15, 23, 42, 0.05);
 192:   padding: 18px 14px 16px;
 193:   z-index: 160;
 194:   opacity: 0;
 195:   visibility: hidden;
 196:   transform: translateY(8px) scale(0.98);
 197:   pointer-events: none;
 198:   transition: opacity 0.22s cubic-bezier(0.16, 1, 0.3, 1),
 199:               transform 0.22s cubic-bezier(0.16, 1, 0.3, 1),
 200:               visibility 0.22s;
 201: }
 202: 
 203: .profile-menu-wrap.is-open .profile-dropdown-card {
 204:   opacity: 1;
 205:   visibility: visible;
 206:   transform: translateY(0) scale(1);
 207:   pointer-events: auto;
 208: }
