 210: /* Diagonal 25% OFF Ribbon on Top-Right Corner */
 211: .profile-ribbon-wrap {
 212:   position: absolute;
 213:   top: -4px;
 214:   right: -4px;
 215:   width: 84px;
 216:   height: 84px;
 217:   overflow: hidden;
 218:   pointer-events: auto;
 219:   z-index: 5;
 220: }
 221: 
 222: .profile-ribbon {
 223:   position: absolute;
 224:   top: 16px;
 225:   right: -24px;
 226:   width: 112px;
 227:   padding: 4px 0;
 228:   background: linear-gradient(135deg, #ffe0c8 0%, #ffc099 100%);
 229:   color: #d96320;
 230:   font-family: 'Poppins', sans-serif;
 231:   font-size: 11px;
 232:   font-weight: 600;
 233:   text-align: center;
 234:   transform: rotate(42deg);
