 352: /* ================= LONGACRES-INSPIRED MEGA DROPDOWN ================= */
 353: .mega-dropdown-wrapper {
 354:   position: absolute;
 355:   top: 100%;
 356:   left: 0;
 357:   right: 0;
 358:   z-index: 120;
 359:   opacity: 0;
 360:   visibility: hidden;
 361:   transform: translateY(4px);
 362:   pointer-events: none;
 363:   transition: opacity 0.15s ease,
 364:               transform 0.15s ease,
 365:               visibility 0.15s;
 366: }
