 374: .mega-skel-title,
 375: .mega-skel-link {
 376:   border-radius: 4px;
 377:   background: linear-gradient(90deg, #f1f5f9 25%, #e2e8f0 50%, #f1f5f9 75%);
 378:   background-size: 200% 100%;
 379:   animation: mega-skel 1.2s ease-in-out infinite;
 380: }
 381: 
 382: .mega-skel-title {
 383:   height: 14px;
 384:   width: 60%;
 385:   margin: 12px 0 10px;
 386: }
 387: 
 388: .mega-skel-link {
