 392: }
 393: 
 394: @keyframes mega-skel {
 395:   to { background-position: -200% 0; }
 396: }
 397: 
 398: .mega-spotlight-skel-img {
 399:   height: 150px;
 400:   border-radius: 4px;
 401:   background: linear-gradient(90deg, #f1f5f9 25%, #e2e8f0 50%, #f1f5f9 75%);
 402:   background-size: 200% 100%;
 403:   animation: mega-skel 1.2s ease-in-out infinite;
 404: }
