 412:   border-radius: 50%;
 413:   animation: mega-spin 0.7s linear infinite;
 414:   vertical-align: -2px;
 415:   margin-right: 6px;
 416: }
 417: 
 418: @keyframes mega-spin {
 419:   to { transform: rotate(360deg); }
 420: }
