  8: export type AuthView = 'login' | 'register' | 'wholesale-register' | 'forgot-password' | 'reset-password';
  9: type AccountView = Exclude<AuthView, 'login'>;
 10: type Errors = Record<string, string[]>;
 11: 
 12: function AuthInput({
 13:   label,
 14:   error,
 15:   lang = 'ar',
 16:   ...props
 17: }: InputHTMLAttributes<HTMLInputElement> & { label: string; error?: string; lang?: 'ar' | 'en' }) {
 18:   const id = `auth-${props.name}`;
 19:   const isPassword = props.type === 'password';
 20:   const [showPwd, setShowPwd] = useState(false);
 21:   const ar = lang === 'ar';
 22: 
 23:   return (
 24:     <div>
 25:       <label className="luxury-field-label" htmlFor={id}>
 26:         {label}
 27:         {props.required && <span className="luxury-req-mark" aria-hidden="true">*</span>}
 28:       </label>
 29:       {isPassword ? (
 30:         <div className="luxury-pwd-wrap">
 31:           <input
 32:             {...props}
 33:             id={id}
 34:             type={showPwd ? 'text' : 'password'}
 35:             className="pill-input pr-pwd"
 36:             aria-invalid={!!error}
 37:             aria-describedby={error ? `${id}-error` : undefined}
 38:           />
 39:           <button
 40:             type="button"
 41:             onClick={() => setShowPwd((v) => !v)}
 42:             className="luxury-eye-btn"
 43:             aria-label={ar ? (showPwd ? 'إخفاء كلمة المرور' : 'إظهار كلمة المرور') : (showPwd ? 'Hide password' : 'Show password')}
 44:             aria-pressed={showPwd}
 45:           >
 46:             <svg
 47:               width="16"
 48:               height="16"
 49:               viewBox="0 0 24 24"
 50:               fill="none"
 51:               stroke="currentColor"
 52:               strokeWidth="1.8"
 53:               strokeLinecap="round"
 54:               strokeLinejoin="round"
 55:             >
 56:               {showPwd ? (
 57:                 <>
 58:                   <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24" />
 59:                   <line x1="1" y1="1" x2="23" y2="23" />
 60:                 </>
 61:               ) : (
 62:                 <>
 63:                   <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" />
 64:                   <circle cx="12" cy="12" r="3" />
 65:                 </>
 66:               )}
 67:             </svg>
 68:           </button>
 69:         </div>
 70:       ) : (
 71:         <input
 72:           {...props}
 73:           id={id}
 74:           className="pill-input"
 75:           aria-invalid={!!error}
 76:           aria-describedby={error ? `${id}-error` : undefined}
 77:         />
 78:       )}
 79:       {error && (
 80:         <p id={`${id}-error`} className="luxury-field-error" role="alert">
 81:           {error}
 82:         </p>
 83:       )}
 84:     </div>
 85:   );
 86: }
 87: 
 88: export function AccountForm({
 89:   view,
 90:   lang,
 91:   onChangeView,
 92:   initialIdentifier = '',
 93:   initialToken = '',
 94: }: {
 95:   view: AccountView;
 96:   lang: 'ar' | 'en';
 97:   onChangeView: (view: AuthView) => void;
 98:   initialIdentifier?: string;
 99:   initialToken?: string;
100: }) {
101:   const router = useRouter();
102:   const { branding } = useBranding();
103:   const ar = lang === 'ar';
104:   const wholesale = view === 'wholesale-register';
105:   const recovery = view === 'forgot-password' || view === 'reset-password';
106:   const [businessStep, setBusinessStep] = useState(false);
107:   const [resetStep, setResetStep] = useState(view === 'reset-password');
108:   const [recoverySent, setRecoverySent] = useState(false);
109:   const [finished, setFinished] = useState(false);
110:   const [busy, setBusy] = useState(false);
111:   const [errors, setErrors] = useState<Errors>({});
112:   const [formError, setFormError] = useState('');
113:   const [notice, setNotice] = useState('');
114:   const [name, setName] = useState('');
115:   const [phone, setPhone] = useState('');
116:   const [email, setEmail] = useState('');
117:   const [password, setPassword] = useState('');
118:   const [confirmation, setConfirmation] = useState('');
119:   const [identifier, setIdentifier] = useState(initialIdentifier);
120:   const [resetToken, setResetToken] = useState(initialToken);
121:   const [company, setCompany] = useState('');
122:   const [taxNumber, setTaxNumber] = useState('');
123:   const [commercialRegister, setCommercialRegister] = useState('');
124:   const [documents, setDocuments] = useState<File[]>([]);
125:   const [codeSent, setCodeSent] = useState(false);
126:   const [code, setCode] = useState('');
127:   const [phoneProof, setPhoneProof] = useState('');
128:   const [resendAt, setResendAt] = useState(0);
129:   const [secondsLeft, setSecondsLeft] = useState(0);
130: 
131:   useEffect(() => {
132:     if (wholesale && businessStep) document.getElementById('auth-company_name')?.focus();
133:   }, [wholesale, businessStep]);
134: 
135:   useEffect(() => {
136:     if (resendAt <= Date.now()) {
137:       setSecondsLeft(0);
138:       return;
139:     }
140:     let interval: number | undefined;
141:     const updateRemaining = () => {
142:       const rem = Math.max(0, Math.ceil((resendAt - Date.now()) / 1000));
143:       setSecondsLeft(rem);
144:       if (rem === 0 && interval !== undefined) window.clearInterval(interval);
145:     };
146:     updateRemaining();
147:     interval = window.setInterval(updateRemaining, 1000);
148:     return () => window.clearInterval(interval);
149:   }, [resendAt]);
150: 
151:   const text = (arabic: string, english: string) => (ar ? arabic : english);
152:   const title = recovery
153:     ? resetStep
154:       ? text('كلمة مرور جديدة', 'New password')
155:       : text('نسيت كلمة المرور؟', 'Forgot password?')
156:     : wholesale
157:       ? text('تسجيل كتاجر جملة', 'Wholesale registration')
158:       : text('إنشاء حساب', 'Create an account');
159:   const subtitle = recovery
160:     ? resetStep
161:       ? text('أدخل رمز الاستعادة وكلمة المرور الجديدة.', 'Enter your recovery code and a new password.')
162:       : text('أدخل بريدك الإلكتروني أو رقم موبايلك لاستعادة حسابك.', 'Enter your email or mobile number to recover your account.')
163:     : wholesale
164:       ? businessStep
165:         ? text('بيانات شركتك ومستنداتها لمراجعة طلب الجملة.', 'Your business details and documents for application review.')
166:         : text('ابدأ ببياناتك، ثم أكمل بيانات نشاطك التجاري.', 'Start with your details, then tell us about your business.')
167:       : text(`أنشئ حسابك في ${branding.name} وتابع طلباتك بسهولة.`, `Create your ${branding.name} account and keep track of your orders.`);
168: 
169:   function handleError(err: unknown) {
170:     const response = (err as { response?: { status?: number; data?: { message?: string; errors?: Errors }; headers?: Record<string, string> } }).response;
171:     if (response?.status === 422) {
172:       const fields = response.data?.errors ?? {};
173:       setErrors(fields);
174:       if (wholesale && ['name', 'phone', 'email', 'password', 'phone_verification_token'].some((key) => fields[key])) setBusinessStep(false);
175:       if (fields.phone_verification_token) {
176:         setPhoneProof('');
177:         setCodeSent(false);
178:         setCode('');
179:       }
180:       if (Object.keys(fields).length === 0) setFormError(response.data?.message ?? text('راجع البيانات وحاول مرة أخرى.', 'Check your details and try again.'));
181:     } else if (response?.status === 429) {
182:       const seconds = response.headers?.['retry-after'] ?? '60';
183:       setFormError(text(`محاولات كثيرة، حاول بعد ${seconds} ثانية.`, `Too many attempts. Try again in ${seconds}s.`));
184:     } else {
185:       setFormError(response?.data?.message ?? text('تعذر الاتصال بالخادم. حاول مرة أخرى.', 'Could not reach the server. Please try again.'));
186:     }
187:   }
188: 
189:   async function submit(event: FormEvent<HTMLFormElement>) {
190:     event.preventDefault();
191:     if (busy) return;
192:     setErrors({});
193:     setFormError('');
194:     setNotice('');
195:     if ((!recovery || resetStep) && password !== confirmation) {
196:       setErrors({ password_confirmation: [text('كلمتا المرور غير متطابقتين.', 'The passwords do not match.')] });
197:       return;
198:     }
199:     if (wholesale && !businessStep) {
200:       setBusinessStep(true);
201:       return;
202:     }
203:     setBusy(true);
204:     try {
205:       if (recovery) {
206:         if (resetStep) {
207:           await resetWebPassword(identifier, resetToken, password, confirmation);
208:           setFinished(true);
209:           setPassword('');
210:           setConfirmation('');
211:           setResetToken('');
212:         } else {
213:           const response = await requestPasswordReset(identifier);
214:           setNotice(response.message);
215:           setRecoverySent(true);
216:         }
217:       } else {
218:         const home = await registerWeb(
219:           {
220:             name: name.trim(),
221:             phone: phone.trim(),
222:             email: email.trim() || undefined,
223:             password,
224:             phone_verification_token: phoneProof || undefined,
225:             ...(wholesale ? { company_name: company.trim(), tax_number: taxNumber.trim(), commercial_register: commercialRegister.trim() } : {}),
226:           },
227:           wholesale,
228:           documents,
229:         );
230:         router.replace(home);
231:       }
232:     } catch (err) {
233:       handleError(err);
234:     } finally {
235:       setBusy(false);
236:     }
237:   }
238: 
239:   async function sendCode() {
240:     if (busy) return;
241:     setFormError('');
242:     setErrors({});
243:     setNotice('');
244:     if (!phone.trim()) {
245:       setErrors({ phone: [text('أدخل رقم الموبايل أولًا.', 'Enter your mobile number first.')] });
246:       return;
247:     }
248:     if (Date.now() < resendAt) {
249:       setNotice(text('انتظر دقيقة قبل طلب رمز آخر.', 'Wait one minute before requesting another code.'));
250:       return;
251:     }
252:     setBusy(true);
253:     try {
254:       const response = await sendPhoneVerification(phone.trim());
255:       setCodeSent(true);
256:       setNotice(response.message);
257:       setResendAt(Date.now() + 60000);
258:     } catch (err) {
259:       handleError(err);
260:     } finally {
261:       setBusy(false);
262:     }
263:   }
264: 
265:   async function confirmPhone() {
266:     if (busy) return;
267:     setErrors({});
268:     setFormError('');
269:     setNotice('');
270:     if (!/^\d{6}$/.test(code)) {
271:       setErrors({ code: [text('أدخل رمز التحقق المكون من 6 أرقام.', 'Enter the 6-digit verification code.')] });
272:       return;
273:     }
274:     setBusy(true);
275:     try {
276:       setPhoneProof(await verifyPhone(phone.trim(), code));
277:       setNotice(text('تم تأكيد رقم الموبايل.', 'Your mobile number is verified.'));
278:     } catch (err) {
279:       handleError(err);
280:     } finally {
281:       setBusy(false);
282:     }
283:   }
284: 
285:   const passwordFields = (
286:     <>
287:       <AuthInput
288:         lang={lang}
289:         name="password"
290:         label={text(resetStep ? 'كلمة المرور الجديدة' : 'كلمة المرور', resetStep ? 'New password' : 'Password')}
291:         type="password"
292:         autoComplete="new-password"
293:         enterKeyHint="next"
294:         required
295:         minLength={8}
296:         maxLength={255}
297:         placeholder={text('8 أحرف على الأقل', 'At least 8 characters')}
298:         value={password}
299:         onChange={(e) => setPassword(e.target.value)}
300:         error={errors.password?.[0]}
301:       />
302:       <AuthInput
303:         lang={lang}
304:         name="password_confirmation"
305:         label={text('تأكيد كلمة المرور', 'Confirm password')}
306:         type="password"
307:         autoComplete="new-password"
308:         enterKeyHint={wholesale ? 'next' : 'done'}
309:         required
310:         minLength={8}
311:         maxLength={255}
312:         placeholder={text('أعد إدخال كلمة المرور', 'Re-enter your password')}
313:         value={confirmation}
314:         onChange={(e) => setConfirmation(e.target.value)}
315:         error={errors.password_confirmation?.[0]}
316:       />
317:     </>
318:   );
319: 
320:   return (
321:     <>
322:       <h1 className="luxury-title" tabIndex={-1}>
323:         {title}
324:       </h1>
325:       <p className="luxury-sub">{subtitle}</p>
326: 
327:       {wholesale && !finished && (
328:         <div className="luxury-stepper" role="group" aria-label={text('خطوات التسجيل', 'Registration steps')}>
329:           <button
330:             type="button"
331:             className="luxury-step-pill"
332:             data-active={!businessStep}
333:             disabled={busy}
334:             onClick={() => {
335:               if (businessStep) {
336:                 setBusinessStep(false);
337:                 setErrors({});
338:                 setFormError('');
339:               }
340:             }}
341:           >
342:             <span>1. {text('البيانات الأساسية', 'Your details')}</span>
343:           </button>
344:           <button
345:             type="button"
346:             className="luxury-step-pill"
347:             data-active={businessStep}
348:             disabled={busy || !businessStep}
349:           >
350:             <span>2. {text('بيانات النشاط', 'Business info')}</span>
351:           </button>
352:         </div>
353:       )}
354: 
355:       {finished ? (
356:         <div className="luxury-success" role="status">
357:           {text('تم تغيير كلمة المرور. يمكنك تسجيل الدخول الآن.', 'Password changed. You can sign in now.')}
358:         </div>
359:       ) : (
360:         <form className="luxury-form" onSubmit={submit}>
361:           <fieldset disabled={busy} className="luxury-auth-fields">
362:             {recovery ? (
363:               <>
364:                 <AuthInput
365:                   lang={lang}
366:                   name="identifier"
367:                   label={text('البريد الإلكتروني أو رقم الموبايل', 'Email or mobile number')}
368:                   type="text"
369:                   inputMode="email"
370:                   autoComplete="username"
371:                   enterKeyHint={resetStep ? 'next' : 'done'}
372:                   required
373:                   maxLength={255}
374:                   dir="ltr"
375:                   placeholder={text('example@domain.com / 01xxxxxxxxx', 'example@domain.com / +201xxxxxxxxx')}
376:                   value={identifier}
377:                   onChange={(e) => {
378:                     setIdentifier(e.target.value);
379:                     setRecoverySent(false);
380:                   }}
381:                   error={errors.email?.[0] ?? errors.phone?.[0]}
382:                 />
383:                 {resetStep && (
384:                   <>
385:                     <AuthInput
386:                       lang={lang}
387:                       name="token"
388:                       label={text('رمز الاستعادة', 'Recovery code')}
389:                       type="text"
390:                       autoComplete="one-time-code"
391:                       enterKeyHint="next"
392:                       required
393:                       minLength={64}
394:                       maxLength={64}
395:                       dir="ltr"
396:                       value={resetToken}
397:                       onChange={(e) => setResetToken(e.target.value)}
398:                       error={errors.token?.[0]}
399:                     />
400:                     {passwordFields}
401:                   </>
402:                 )}
403:               </>
404:             ) : wholesale && businessStep ? (
405:               <>
406:                 <AuthInput
407:                   lang={lang}
408:                   name="company_name"
409:                   label={text('اسم الشركة أو النشاط التجاري', 'Business name')}
410:                   autoComplete="organization"
411:                   enterKeyHint="next"
412:                   required
413:                   maxLength={255}
414:                   value={company}
415:                   onChange={(e) => setCompany(e.target.value)}
416:                   error={errors.company_name?.[0]}
417:                 />
418:                 <AuthInput
419:                   lang={lang}
420:                   name="tax_number"
421:                   label={text('الرقم الضريبي', 'Tax number')}
422:                   inputMode="numeric"
423:                   enterKeyHint="next"
424:                   required
425:                   maxLength={50}
426:                   dir="ltr"
427:                   value={taxNumber}
428:                   onChange={(e) => setTaxNumber(e.target.value)}
429:                   error={errors.tax_number?.[0]}
430:                 />
431:                 <AuthInput
432:                   lang={lang}
433:                   name="commercial_register"
434:                   label={text('رقم السجل التجاري', 'Commercial register number')}
435:                   inputMode="numeric"
436:                   enterKeyHint="done"
437:                   required
438:                   maxLength={50}
439:                   dir="ltr"
440:                   value={commercialRegister}
441:                   onChange={(e) => setCommercialRegister(e.target.value)}
442:                   error={errors.commercial_register?.[0]}
443:                 />
444:                 <div>
445:                   <label className="luxury-field-label" htmlFor="auth-documents">
446:                     {text('مستندات الشركة', 'Business documents')}
447:                     <span className="luxury-req-mark" aria-hidden="true">*</span>
448:                   </label>
449:                   <p className="luxury-field-hint" id="documents-hint">
450:                     {text('من 1 إلى 5 ملفات PDF أو JPG أو PNG، حتى 5 ميجابايت للملف.', '1–5 PDF, JPG or PNG files, up to 5 MB each.')}
451:                   </p>
452:                   <div className="luxury-file-picker">
453:                   <span aria-hidden="true">{documents.length ? text('تغيير المستندات', 'Change documents') : text('اختيار المستندات', 'Choose documents')}</span>
454:                   <input
455:                     id="auth-documents"
456:                     className="luxury-file-input"
457:                     name="documents"
458:                     type="file"
459:                     accept=".pdf,.jpg,.jpeg,.png"
460:                     multiple
461:                     required={documents.length === 0}
462:                     aria-label={text('اختيار مستندات الشركة', 'Choose business documents')}
463:                     aria-describedby="documents-hint documents-error"
464:                     onChange={(e) => {
465:                       const selected = Array.from(e.target.files ?? []);
466:                       if (selected.length > 5 || selected.some((f) => f.size > 5 * 1024 * 1024 || !/\.(pdf|jpe?g|png)$/i.test(f.name))) {
467:                         setErrors({ documents: [text('اختر حتى 5 ملفات PDF أو صور، بحجم 5 ميجابايت أو أقل لكل ملف.', 'Choose up to 5 PDF or image files, no larger than 5 MB each.')] });
468:                         setDocuments([]);
469:                         e.target.value = '';
470:                         return;
471:                       }
472:                       setDocuments(selected);
473:                       // React owns the chosen files. Clear the native input so
474:                       // removal restores required validation and reselection works.
475:                       e.currentTarget.value = '';
476:                       setErrors({});
477:                     }}
478:                   />
479:                   </div>
480:                   {documents.length > 0 && (
481:                     <ul className="luxury-file-list">
482:                       {documents.map((file, index) => (
483:                         <li key={`${file.name}-${index}`}>
484:                           <span>{file.name}</span>
485:                           <button
486:                             type="button"
487:                             className="luxury-file-remove"
488:                             aria-label={text(`إزالة ${file.name}`, `Remove ${file.name}`)}
489:                             onClick={() => setDocuments((prev) => prev.filter((_, i) => i !== index))}
490:                           >
491:                             ✕
492:                           </button>
493:                         </li>
494:                       ))}
495:                     </ul>
496:                   )}
497:                   <div id="documents-error">
498:                     {Object.entries(errors)
499:                       .filter(([key]) => key === 'documents' || key.startsWith('documents.'))
500:                       .map(([key, messages]) => (
501:                         <p key={key} className="luxury-field-error" role="alert">
502:                           {messages[0]}
503:                         </p>
504:                       ))}
505:                   </div>
506:                 </div>
507:               </>
508:             ) : (
509:               <>
510:                 <AuthInput
511:                   lang={lang}
512:                   name="name"
513:                   label={text('الاسم الكامل', 'Full name')}
514:                   autoComplete="name"
515:                   enterKeyHint="next"
516:                   required
517:                   maxLength={255}
518:                   value={name}
519:                   onChange={(e) => setName(e.target.value)}
520:                   error={errors.name?.[0]}
521:                 />
522:                 <div>
523:                   <AuthInput
524:                     lang={lang}
525:                     name="phone"
526:                     label={text('رقم الموبايل', 'Mobile number')}
527:                     type="tel"
528:                     inputMode="tel"
529:                     autoComplete="tel"
530:                     enterKeyHint="next"
531:                     required
532:                     maxLength={30}
533:                     dir="ltr"
534:                     placeholder={text('01xxxxxxxxx', '+201xxxxxxxxx')}
535:                     value={phone}
536:                     onChange={(e) => {
537:                       setPhone(e.target.value);
538:                       setPhoneProof('');
539:                       setCodeSent(false);
540:                       setCode('');
541:                       setNotice('');
542:                       setResendAt(0);
543:                     }}
544:                     error={errors.phone?.[0] ?? errors.phone_verification_token?.[0]}
545:                   />
546:                   {phoneProof ? (
547:                     <p className="luxury-field-hint luxury-verified-badge" role="status">
548:                     {text('رقم الموبايل مؤكّد', 'Mobile number verified')}
549:                     </p>
550:                   ) : (
551:                     <div className="luxury-inline-action-row">
552:                       <button type="button" className="luxury-inline-action" disabled={secondsLeft > 0} onClick={sendCode}>
553:                         {codeSent ? text('إعادة إرسال رمز التحقق', 'Resend verification code') : text('إرسال رمز التحقق', 'Send verification code')}
554:                       </button>
555:                       {secondsLeft > 0 && (
556:                         <span className="luxury-countdown-badge" role="timer" aria-live="off">
557:                           {text(`${secondsLeft} ث`, `${secondsLeft}s`)}
558:                         </span>
559:                       )}
560:                     </div>
561:                   )}
562:                   {codeSent && !phoneProof && (
563:                     <div className="luxury-phone-verification">
564:                       <AuthInput
565:                         lang={lang}
566:                         name="code"
567:                         label={text('رمز التحقق', 'Verification code')}
568:                         inputMode="numeric"
569:                         autoComplete="one-time-code"
570:                         enterKeyHint="done"
571:                         maxLength={6}
572:                         dir="ltr"
573:                         placeholder="000000"
574:                         value={code}
575:                         onChange={(e) => setCode(e.target.value.replace(/\D/g, ''))}
576:                         error={errors.code?.[0]}
577:                       />
578:                       <button type="button" className="luxury-secondary-button" onClick={confirmPhone}>
579:                         {text('تأكيد الرقم', 'Verify number')}
580:                       </button>
581:                     </div>
582:                   )}
583:                 </div>
584:                 <AuthInput
585:                   lang={lang}
586:                   name="email"
