 70:       if (event.data.authenticated === true) window.location.replace(new URL('/dashboard', office).href);
 71:       else setStaffCheckPending(false);
 72:     };
 73:     window.addEventListener('message', receive);
 74:     document.body.appendChild(frame);
 75:     const timer = window.setTimeout(() => setStaffCheckPending(false), 5000);
