130:   // Canvas drawing routine
131:   const renderCanvas = useCallback(() => {
132:     const canvas = canvasRef.current;
133:     if (!canvas) return;
134:     const ctx = canvas.getContext('2d');
135:     if (!ctx) return;
136: 
137:     ctx.fillStyle = '#ffffff';
138:     ctx.fillRect(0, 0, W, H);
139: 
140:     const activePixels = birkinPixelsRef.current;
141:     if (!activePixels) return;
142: 
143:     const step = gridStep;
144:     const half = step / 2;
145:     const { x: mx, y: my, isHovering: isHover } = mousePosRef.current;
146: 
147:     ctx.fillStyle = '#09090b';
148: 
149:     for (let y = Math.floor(half); y < H; y += step) {
150:       for (let x = Math.floor(half); x < W; x += step) {
151:         const idx = (y * W + x) * 4;
152:         const luma = activePixels[idx] / 255.0;
153:         const dark = 1.0 - luma;
154:         if (dark < 0.06) continue;
155: 
156:         let drawX = x;
157:         let drawY = y;
158:         let scaleBoost = 1.0;
159: 
160:         if (isHover) {
161:           const dx = x - mx;
162:           const dy = y - my;
163:           const dist = Math.sqrt(dx * dx + dy * dy);
164:           if (dist < 110) {
165:             const factor = 1.0 - dist / 110.0;
166:             drawX += (dx / (dist + 1)) * factor * 2.2;
167:             drawY += (dy / (dist + 1)) * factor * 2.2;
168:             scaleBoost = 1.0 + factor * 0.16;
169:           }
170:         }
171: 
172:         const r = Math.pow(dark, 0.92) * (step * 0.68) * scaleBoost;
173:         if (r < 0.45) continue;
174: 
175:         // Diamond dot
176:         ctx.beginPath();
177:         ctx.moveTo(drawX, drawY - r);
178:         ctx.lineTo(drawX + r, drawY);
179:         ctx.lineTo(drawX, drawY + r);
180:         ctx.lineTo(drawX - r, drawY);
181:         ctx.closePath();
182:         ctx.fill();
183: 
184:         // White micro center dot
185:         if (dark > 0.76 && r > 2.4) {
186:           const ir = (dark - 0.74) * (step * 0.3);
187:           if (ir >= 0.7) {
188:             ctx.save();
189:             ctx.fillStyle = '#ffffff';
190:             ctx.beginPath();
191:             ctx.arc(drawX, drawY, ir, 0, Math.PI * 2);
192:             ctx.fill();
193:             ctx.restore();
194:           }
195:         }
196:       }
197:     }
198:   }, []);
