205:   // Extract pixel buffers on mount
206:   useEffect(() => {
207:     const offCanvas = document.createElement('canvas');
208:     offCanvas.width = W;
209:     offCanvas.height = H;
210:     const offCtx = offCanvas.getContext('2d', { willReadFrequently: true });
211:     if (!offCtx) return;
212: 
213:     const extract = (img: HTMLImageElement) => {
214:       offCtx.fillStyle = '#ffffff';
215:       offCtx.fillRect(0, 0, W, H);
216:       offCtx.drawImage(img, 0, 0, W, H);
217:       return offCtx.getImageData(0, 0, W, H).data;
218:     };
219: 
220:     const bImg = new Image();
221:     bImg.src = BIRKIN_IMG_DATA;
222:     bImg.onload = () => {
223:       birkinPixelsRef.current = extract(bImg);
224:       renderCanvasRef.current();
225:     };
226: 
227:     return () => {
228:       bImg.onload = null;
229:     };
230:   }, []);
