236:     if (!canvas) return;
237:     const rect = canvas.getBoundingClientRect();
238:     mousePosRef.current = {
239:       x: ((clientX - rect.left) / rect.width) * W,
240:       y: ((clientY - rect.top) / rect.height) * H,
