421:                                 <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" />
422:                                 <circle cx="12" cy="12" r="3" />
423:                               </>
424:                             )}
425:                           </svg>
426:                         </button>
427:                       </div>
428:                       {errors.password?.[0] && (
429:                         <p id="password-error" className="luxury-field-error" role="alert">
430:                           {errors.password[0]}
431:                         </p>
432:                       )}
433:                     </div>
434: 
435:                     {formError && (
436:                       <p className="luxury-form-error" role="alert">
437:                         {formError}
438:                       </p>
439:                     )}
440: 
441:                     <div style={{ paddingTop: '4px' }}>
442:                       <button
443:                         type="submit"
444:                         disabled={!isReady || staffCheckPending || isSubmitting}
445:                         className="pill-btn-primary"
446:                       >
447:                         {isSubmitting ? (
448:                           <span>{lang === 'ar' ? 'جاري التحقق...' : 'Signing in...'}</span>
449:                         ) : (
450:                           <span>{t.signInBtn}</span>
451:                         )}
452:                       </button>
453:                     </div>
454:                   </form>
455: 
456:                   {/* Bottom links in Thumb Reach Zone */}
457:                   <div className="luxury-bottom-switch">
458:                     <button
459:                       type="button"
460:                       disabled={!isReady || isSubmitting}
461:                       onClick={() => setView('forgot-password')}
462:                       className="luxury-switch-link"
463:                     >
464:                       {t.forgotPassword}
465:                     </button>
466:                     <span className="luxury-link-sep">·</span>
467:                     <button
468:                       type="button"
469:                       disabled={!isReady || isSubmitting}
470:                       onClick={() => setView('register')}
471:                       className="luxury-switch-link"
472:                     >
473:                       {t.createAccount}
474:                     </button>
475:                     <span className="luxury-link-sep">·</span>
476:                     <button
477:                       type="button"
478:                       disabled={!isReady || isSubmitting}
479:                       onClick={() => setView('wholesale-register')}
480:                       className="luxury-switch-link"
481:                     >
482:                       {t.wholesaleRegister}
483:                     </button>
484:                   </div>
485:                 </>
486:               ) : (
487:                 <AccountForm
488:                   key={view}
489:                   view={view}
490:                   lang={lang}
491:                   onChangeView={setView}
492:                   initialIdentifier={params.get('email') ?? params.get('phone') ?? login}
493:                   initialToken={params.get('token') ?? ''}
494:                 />
495:               )}
496:             </div>
497:           </section>
498: 
499:           {/* ================= RIGHT COLUMN: LUXURY HANDBAG HALFTONE ARTWORK ================= */}
500:           <section
501:             className="luxury-right-col"
502:             aria-label={lang === 'ar' ? 'حقيبة بيركن بتقنية الهالفتون' : 'Birkin Halftone artwork'}
503:           >
504:             <canvas
505:               ref={canvasRef}
506:               width={W}
507:               height={H}
508:               aria-hidden="true"
509:               onMouseMove={(e) => handlePointerMove(e.clientX, e.clientY)}
510:               onMouseLeave={handlePointerLeave}
511:               onTouchMove={(e) => {
512:                 if (e.touches && e.touches[0]) {
513:                   handlePointerMove(e.touches[0].clientX, e.touches[0].clientY);
514:                 }
515:               }}
516:             />
517:           </section>
518:         </div>
519:       </main>
520:     </div>
521:   );
522: };
523: 
524: export default LoginScreen;
